window.PK=window.PK||{};window.PK.glossar=[{"slug":"5-amino-1mq","begriff":"5-Amino-1MQ","begriff_en":"5-Amino-1MQ","kategorie":"wirkstoff","kurz":"Mała cząsteczka badana jako inhibitor NNMT w modelach przedklinicznych. Nie jest peptydem.","kurz_en":"Mała cząsteczka badana jako inhibitor NNMT w modelach przedklinicznych. Nie jest peptydem.","quellen":[{"titel":"PubMed: Publikacja badawcza, PMID 29155147","titel_en":"PubMed: Publikacja badawcza, PMID 29155147","url":"https://pubmed.ncbi.nlm.nih.gov/29155147/"}],"text":"Powiązana publikacja źródłowa bada małocząsteczkowe inhibitory NNMT w testach komórkowych oraz w modelu otyłości indukowanej dietą u myszy. Nie dostarcza dowodów klinicznych dla stosowania produktów sklepowych.","text_en":"Powiązana publikacja źródłowa bada małocząsteczkowe inhibitory NNMT w testach komórkowych oraz w modelu otyłości indukowanej dietą u myszy. Nie dostarcza dowodów klinicznych dla stosowania produktów sklepowych.","synonyme":["5-Amino 1MQ","5A1MQ","Inhibitor NNMT"],"synonyme_en":["5-Amino 1MQ","5A1MQ","Inhibitor NNMT"],"link":"wirkstoffe/5-amino-1mq.html"},{"slug":"affiliate-link","begriff":"Link afiliacyjny","begriff_en":"Link afiliacyjny","kategorie":"vergleich","kurz":"Link afiliacyjny prowadzi do zewnętrznego sklepu i może wywołać prowizję od zakupu.","kurz_en":"Link afiliacyjny prowadzi do zewnętrznego sklepu i może wywołać prowizję od zakupu.","quellen":[{"titel":"Peptide Compass: Nasza informacja o afiliacji","titel_en":"Peptide Compass: Nasza informacja o afiliacji","url":"https://peptidkompass.com/pl/affiliate-hinweis.html"}],"text":"Linki afiliacyjne mają etykietę Reklama bezpośrednio przy linku i dodatkowo używają atrybutu sponsored nofollow. Etykieta dotyczy także linków do sklepów bez potwierdzonego partnerstwa. Status partnera i ewentualna prowizja nie zmieniają sposobu oceny dostawcy.","text_en":"Linki afiliacyjne mają etykietę Reklama bezpośrednio przy linku i dodatkowo używają atrybutu sponsored nofollow. Etykieta dotyczy także linków do sklepów bez potwierdzonego partnerstwa. Status partnera i ewentualna prowizja nie zmieniają sposobu oceny dostawcy.","siehe":["partnercode"],"seiten":["affiliate-hinweis.html"]},{"slug":"agonist","begriff":"Agonista","begriff_en":"Agonista","kategorie":"grundlagen","kurz":"Cząsteczka, która wiąże się z receptorem i uruchamia jego szlak sygnałowy. Przeciwieństwo: antagonista.","kurz_en":"Cząsteczka, która wiąże się z receptorem i uruchamia jego szlak sygnałowy. Przeciwieństwo: antagonista.","quellen":[{"titel":"NCI: agonista","titel_en":"NCI: agonista","url":"https://www.cancer.gov/publications/dictionaries/cancer-terms/def/agonist"}],"text":"Agonista wiąże się z receptorem i aktywuje powiązany z nim szlak sygnałowy, podobnie jak klucz otwierający zamek. Odpowiednikiem jest antagonista: również wiąże się z receptorem, ale nie uruchamia szlaku sygnałowego, tylko zajmuje miejsce wiązania i blokuje przyłączenie agonisty. Badania wykorzystują obie role do ukierunkowanego badania szlaków sygnałowych receptorów.","text_en":"Agonista wiąże się z receptorem i aktywuje powiązany z nim szlak sygnałowy, podobnie jak klucz otwierający zamek. Odpowiednikiem jest antagonista: również wiąże się z receptorem, ale nie uruchamia szlaku sygnałowego, tylko zajmuje miejsce wiązania i blokuje przyłączenie agonisty. Badania wykorzystują obie role do ukierunkowanego badania szlaków sygnałowych receptorów.","siehe":["rezeptor","analogon"]},{"slug":"aliquot","begriff":"Alikwot","begriff_en":"Alikwot","kategorie":"handhabung","kurz":"Alikwot to niewielka, odmierzona porcja pobrana z większego roztworu laboratoryjnego, zwykle przechowywana osobno.","kurz_en":"Alikwot to niewielka, odmierzona porcja pobrana z większego roztworu laboratoryjnego, zwykle przechowywana osobno.","quellen":[{"titel":"Hoofnagle et al. (2016): Analiza peptydów i postępowanie w laboratorium","titel_en":"Hoofnagle et al. (2016): Analiza peptydów i postępowanie w laboratorium","url":"https://pubmed.ncbi.nlm.nih.gov/26719571/"}],"text":"Alikwot to wydzielona porcja próbki. Podział na osobne porcje pozwala uniknąć wielokrotnych zmian temperatury całego zapasu.","text_en":"Alikwot to wydzielona porcja próbki. Podział na osobne porcje pozwala uniknąć wielokrotnych zmian temperatury całego zapasu.","siehe":["vial","konzentration","sterilitaet"]},{"slug":"aminosaeure","begriff":"Aminokwas","begriff_en":"Aminokwas","kategorie":"grundlagen","kurz":"Podstawowy budulec, z którego za pomocą wiązań peptydowych powstają peptydy i białka.","kurz_en":"Podstawowy budulec, z którego za pomocą wiązań peptydowych powstają peptydy i białka.","quellen":[{"titel":"NCI: aminokwas","titel_en":"NCI: aminokwas","url":"https://www.cancer.gov/publications/dictionaries/cancer-terms/def/amino-acid"}],"text":"Aminokwasy zawierają grupę aminową i grupę karboksylową. Białka opisuje się zwykle za pomocą 20 standardowych aminokwasów. Wiązania peptydowe łączą je w łańcuchy; ich kolejność nazywa się sekwencją.","text_en":"Aminokwasy zawierają grupę aminową i grupę karboksylową. Białka opisuje się zwykle za pomocą 20 standardowych aminokwasów. Wiązania peptydowe łączą je w łańcuchy; ich kolejność nazywa się sekwencją.","synonyme":["Aminokwasy"],"synonyme_en":["Aminokwasy"],"siehe":["peptid","peptidbindung","sequenz"],"seiten":["peptid-1x1.html"]},{"slug":"analogon","begriff":"Analog","begriff_en":"Analog","kategorie":"grundlagen","kurz":"Syntetycznie zmodyfikowany wariant endogennego peptydu o nieco zmienionej strukturze.","kurz_en":"Syntetycznie zmodyfikowany wariant endogennego peptydu o nieco zmienionej strukturze.","quellen":[{"titel":"EMA: Semaglutyd jako analog GLP-1","titel_en":"EMA: Semaglutyd jako analog GLP-1","url":"https://www.ema.europa.eu/en/medicines/human/EPAR/ozempic"}],"text":"Analog to wytworzony w laboratorium wariant naturalnie występującego peptydu, w którym pojedyncze aminokwasy zamieniono, dodano lub usunięto. Badacze wykorzystują takie zmiany struktury, aby w ukierunkowany sposób badać właściwości, na przykład trwałość lub sposób wiązania z receptorem. Przykładem jest semaglutyd, analog endogennego hormonu GLP-1.","text_en":"Analog to wytworzony w laboratorium wariant naturalnie występującego peptydu, w którym pojedyncze aminokwasy zamieniono, dodano lub usunięto. Badacze wykorzystują takie zmiany struktury, aby w ukierunkowany sposób badać właściwości, na przykład trwałość lub sposób wiązania z receptorem. Przykładem jest semaglutyd, analog endogennego hormonu GLP-1.","synonyme":["Analogi"],"synonyme_en":["Analogi"],"siehe":["peptid","fragment","agonist"]},{"slug":"antimikrobielles-peptid","begriff":"Peptydy przeciwdrobnoustrojowe","begriff_en":"Peptydy przeciwdrobnoustrojowe","kategorie":"klassen","kurz":"Peptydy przeciwdrobnoustrojowe są częścią wrodzonej odporności i powstają w skórze oraz błonach śluzowych.","kurz_en":"Peptydy przeciwdrobnoustrojowe są częścią wrodzonej odporności i powstają w skórze oraz błonach śluzowych.","quellen":[{"titel":"NCBI Bookshelf: Wrodzony układ odpornościowy","titel_en":"NCBI Bookshelf: Wrodzony układ odpornościowy","url":"https://www.ncbi.nlm.nih.gov/books/NBK459455/"}],"text":"Peptydy przeciwdrobnoustrojowe, zwane też AMP lub peptydami obronnymi gospodarza, są elementem wrodzonej odporności. Wytwarzają je komórki skóry i błon śluzowych oraz komórki układu odpornościowego, a po wbudowaniu się w błony bakterii, grzybów lub wirusów działają na nie bezpośrednio. Najlepiej poznaną grupą u ludzi są katelicydyny, których jedyną aktywną formą u człowieka jest LL-37. Poza tym bezpośrednim mechanizmem błonowym AMP bada się również jako cząsteczki sygnałowe układu odpornościowego.","text_en":"Peptydy przeciwdrobnoustrojowe, zwane też AMP lub peptydami obronnymi gospodarza, są elementem wrodzonej odporności. Wytwarzają je komórki skóry i błon śluzowych oraz komórki układu odpornościowego, a po wbudowaniu się w błony bakterii, grzybów lub wirusów działają na nie bezpośrednio. Najlepiej poznaną grupą u ludzi są katelicydyny, których jedyną aktywną formą u człowieka jest LL-37. Poza tym bezpośrednim mechanizmem błonowym AMP bada się również jako cząsteczki sygnałowe układu odpornościowego.","synonyme":["AMP","Peptydy obronne gospodarza"],"synonyme_en":["AMP","Peptydy obronne gospodarza"],"siehe":["protein","peptid"],"wirkstoffe":["ll-37"],"seiten":["peptid-1x1.html"]},{"slug":"aod-9604","begriff":"AOD-9604","begriff_en":"AOD-9604","kategorie":"wirkstoff","kurz":"Zmodyfikowany fragment hormonu wzrostu badany w badaniach metabolicznych.","kurz_en":"Zmodyfikowany fragment hormonu wzrostu badany w badaniach metabolicznych.","quellen":[{"titel":"PubMed: Publikacja badawcza, PMID 11146367","titel_en":"PubMed: Publikacja badawcza, PMID 11146367","url":"https://pubmed.ncbi.nlm.nih.gov/11146367/"}],"text":"Cytowana publikacja źródłowa bada AOD-9604 u szczurów Zucker. Wyników z tego modelu zwierzęcego nie można bezpośrednio przenosić na ludzi ani na produkty sprzedawane przez dostawców materiałów badawczych.","text_en":"Cytowana publikacja źródłowa bada AOD-9604 u szczurów Zucker. Wyników z tego modelu zwierzęcego nie można bezpośrednio przenosić na ludzi ani na produkty sprzedawane przez dostawców materiałów badawczych.","synonyme":["Lek przeciw otyłości 9604","Tyr-hGH Frag 177-191"],"synonyme_en":["Lek przeciw otyłości 9604","Tyr-hGH Frag 177-191"],"link":"wirkstoffe/aod-9604.html"},{"slug":"arzneimittel","begriff":"Produkt leczniczy","begriff_en":"Produkt leczniczy","kategorie":"recht","kurz":"Produkt leczniczy jest prawnie definiowany jako substancja przeznaczona do leczenia lub zapobiegania chorobom u ludzi.","kurz_en":"Produkt leczniczy jest prawnie definiowany jako substancja przeznaczona do leczenia lub zapobiegania chorobom u ludzi.","quellen":[{"titel":"Niemiecka ustawa o lekach, § 2: definicja leków","titel_en":"Niemiecka ustawa o lekach, § 2: definicja leków","url":"https://www.gesetze-im-internet.de/amg_1976/__2.html"}],"text":"§ 2 niemieckiej ustawy o lekach (Arzneimittelgesetz) obejmuje substancje ze względu na ich zamierzone zastosowanie w chorobach oraz niektóre funkcje farmakologiczne, immunologiczne lub metaboliczne. Klasyfikacja jest odrębna od pozwolenia na dopuszczenie do obrotu. Oznaczenie RUO nie wyklucza automatycznie statusu produktu leczniczego.","text_en":"§ 2 niemieckiej ustawy o lekach (Arzneimittelgesetz) obejmuje substancje ze względu na ich zamierzone zastosowanie w chorobach oraz niektóre funkcje farmakologiczne, immunologiczne lub metaboliczne. Klasyfikacja jest odrębna od pozwolenia na dopuszczenie do obrotu. Oznaczenie RUO nie wyklucza automatycznie statusu produktu leczniczego.","synonyme":["Lek"],"synonyme_en":["Lek"],"siehe":["ruo","zulassung","rezeptpflicht"],"seiten":["peptid-1x1.html"]},{"slug":"bakteriostatisches-wasser","begriff":"Woda bakteriostatyczna","begriff_en":"Woda bakteriostatyczna","kategorie":"handhabung","kurz":"Woda bakteriostatyczna to woda jałowa z konserwantem, zwykle alkoholem benzylowym, do roztworów używanych wielokrotnie.","kurz_en":"Woda bakteriostatyczna to woda jałowa z konserwantem, zwykle alkoholem benzylowym, do roztworów używanych wielokrotnie.","quellen":[{"titel":"DailyMed: Woda bakteriostatyczna, skład","titel_en":"DailyMed: Woda bakteriostatyczna, skład","url":"https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=87d6e9dc-fe3b-4593-ac9a-d7493d1959c7"}],"text":"Bakteriostatyczny oznacza, że wzrost bakterii jest hamowany. Skład zależy od produktu; preparaty lecznicze mogą zawierać alkohol benzylowy. Ten opis nie potwierdza ani zgodności z konkretnym peptydem, ani bezpieczeństwa produktu sklepowego.","text_en":"Bakteriostatyczny oznacza, że wzrost bakterii jest hamowany. Skład zależy od produktu; preparaty lecznicze mogą zawierać alkohol benzylowy. Ten opis nie potwierdza ani zgodności z konkretnym peptydem, ani bezpieczeństwa produktu sklepowego.","synonyme":["Woda BAC"],"synonyme_en":["Woda BAC"],"siehe":["steriles-wasser","rekonstitution","sterilitaet"]},{"slug":"bioregulator","begriff":"Bioregulatory","begriff_en":"Bioregulatory","kategorie":"klassen","kurz":"Bioregulatory to bardzo krótkie peptydy syntetyczne złożone z dwóch do czterech aminokwasów, badane w układach narządowych.","kurz_en":"Bioregulatory to bardzo krótkie peptydy syntetyczne złożone z dwóch do czterech aminokwasów, badane w układach narządowych.","quellen":[{"titel":"Khavinson et al. (2003): Hipoteza regulacji genów","titel_en":"Khavinson et al. (2003): Hipoteza regulacji genów","url":"https://pubmed.ncbi.nlm.nih.gov/14666197/"}],"text":"W części badań nad peptydami termin ten opisuje krótkie sekwencje badane pod kątem udziału w regulacji genów. Nie jest to kategoria regulacyjna potwierdzająca skuteczność. Pojedyncze wyniki komórkowe nie dowodzą ani korzyści swoistych dla narządów, ani wydłużenia życia człowieka.","text_en":"W części badań nad peptydami termin ten opisuje krótkie sekwencje badane pod kątem udziału w regulacji genów. Nie jest to kategoria regulacyjna potwierdzająca skuteczność. Pojedyncze wyniki komórkowe nie dowodzą ani korzyści swoistych dla narządów, ani wydłużenia życia człowieka.","synonyme":["Peptydowe bioregulatory","Peptydy Khavinsona"],"synonyme_en":["Peptydowe bioregulatory","Peptydy Khavinsona"],"siehe":["oligopeptid","peptid"],"wirkstoffe":["epitalon"],"seiten":["peptid-1x1.html"]},{"slug":"bioverfuegbarkeit","begriff":"Biodostępność","begriff_en":"Biodostępność","kategorie":"grundlagen","kurz":"Odsetek substancji, który dociera do krwiobiegu w niezmienionej postaci i można go tam zmierzyć.","kurz_en":"Odsetek substancji, który dociera do krwiobiegu w niezmienionej postaci i można go tam zmierzyć.","quellen":[{"titel":"NCBI Bookshelf: Biodostępność leku","titel_en":"NCBI Bookshelf: Biodostępność leku","url":"https://www.ncbi.nlm.nih.gov/books/NBK557852/"}],"text":"Biodostępność wskazuje, jaka część podanej substancji ostatecznie dociera w niezmienionej postaci do krążenia ogólnoustrojowego; wyraża się ją w procentach. Zależy to częściowo od tego, w jakim stopniu substancja jest rozkładana przez enzymy, na przykład w wyniku proteolizy, w drodze przez organizm. Badania farmakokinetyczne określają biodostępność osobno dla różnych dróg podania.","text_en":"Biodostępność wskazuje, jaka część podanej substancji ostatecznie dociera w niezmienionej postaci do krążenia ogólnoustrojowego; wyraża się ją w procentach. Zależy to częściowo od tego, w jakim stopniu substancja jest rozkładana przez enzymy, na przykład w wyniku proteolizy, w drodze przez organizm. Badania farmakokinetyczne określają biodostępność osobno dla różnych dróg podania.","siehe":["halbwertszeit","proteolyse"]},{"slug":"blindtest","begriff":"Test w ślepej próbie","begriff_en":"Test w ślepej próbie","kategorie":"labor","kurz":"Test w ślepej próbie: osoby zaangażowane nie znają istotnych szczegółów dotyczących próbki.","kurz_en":"Test w ślepej próbie: osoby zaangażowane nie znają istotnych szczegółów dotyczących próbki.","quellen":[{"titel":"Karanicolas et al. (2010): Zaślepienie i jego ograniczenia","titel_en":"Karanicolas et al. (2010): Zaślepienie i jego ograniczenia","url":"https://pubmed.ncbi.nlm.nih.gov/20858381/"},{"titel":"Peptide Compass: Metodologia i ograniczenia weryfikacji","titel_en":"Peptide Compass: Metodologia i ograniczenia weryfikacji","url":"https://peptidkompass.com/pl/methodik.html"}],"text":"W laboratoryjnym teście w ślepej próbie informacje o pochodzeniu próbki są przed analizą ukrywane. Może to ograniczyć efekt oczekiwań, ale nie wyklucza błędów ani stronniczości. Nadal liczą się pobieranie próbek, metody i udokumentowana identyfikowalność. Peptide Compass nie przeprowadza własnych testów w ślepej próbie.","text_en":"W laboratoryjnym teście w ślepej próbie informacje o pochodzeniu próbki są przed analizą ukrywane. Może to ograniczyć efekt oczekiwań, ale nie wyklucza błędów ani stronniczości. Nadal liczą się pobieranie próbek, metody i udokumentowana identyfikowalność. Peptide Compass nie przeprowadza własnych testów w ślepej próbie.","siehe":["drittlabor","coa"],"seiten":["methodik.html"]},{"slug":"bpc-157","begriff":"BPC-157","begriff_en":"BPC-157","kategorie":"wirkstoff","kurz":"Syntetyczny peptyd badany w modelach przedklinicznych.","kurz_en":"Syntetyczny peptyd badany w modelach przedklinicznych.","quellen":[{"titel":"PubMed: Publikacja badawcza, PMID 27847966","titel_en":"PubMed: Publikacja badawcza, PMID 27847966","url":"https://pubmed.ncbi.nlm.nih.gov/27847966/"}],"text":"Powiązane badanie komórkowe i na zwierzętach analizuje tworzenie naczyń krwionośnych i sygnalizację VEGFR2. Takie wyniki przedkliniczne nie dowodzą skuteczności ani bezpieczeństwa stosowania u ludzi.","text_en":"Powiązane badanie komórkowe i na zwierzętach analizuje tworzenie naczyń krwionośnych i sygnalizację VEGFR2. Takie wyniki przedkliniczne nie dowodzą skuteczności ani bezpieczeństwa stosowania u ludzi.","synonyme":["Body Protection Compound 157","PL 14736"],"synonyme_en":["Body Protection Compound 157","PL 14736"],"link":"wirkstoffe/bpc-157.html"},{"slug":"cagrilintid","begriff":"Cagrilintide","begriff_en":"Cagrilintide","kategorie":"wirkstoff","kurz":"Syntetyczny analog amyliny badany w badaniach metabolicznych.","kurz_en":"Syntetyczny analog amyliny badany w badaniach metabolicznych.","quellen":[{"titel":"PubMed: Publikacja badawcza, PMID 34288673","titel_en":"PubMed: Publikacja badawcza, PMID 34288673","url":"https://pubmed.ncbi.nlm.nih.gov/34288673/"}],"text":"Cytowana publikacja dotycząca rozwoju opisuje budowę i wybór długo działającego analogu amyliny. Lek badany należy odróżniać od substancji chemicznej do celów badawczych sprzedawanej pod tą samą nazwą.","text_en":"Cytowana publikacja dotycząca rozwoju opisuje budowę i wybór długo działającego analogu amyliny. Lek badany należy odróżniać od substancji chemicznej do celów badawczych sprzedawanej pod tą samą nazwą.","synonyme":["AM833","NN9838"],"synonyme_en":["AM833","NN9838"],"link":"wirkstoffe/cagrilintid.html"},{"slug":"charge","begriff":"Partia","begriff_en":"Partia","kategorie":"labor","kurz":"Partia to pojedynczy cykl produkcyjny z własnym numerem partii, do którego faktycznie odnosi się CoA.","kurz_en":"Partia to pojedynczy cykl produkcyjny z własnym numerem partii, do którego faktycznie odnosi się CoA.","quellen":[{"titel":"ICH Q7: Produkcja, partie i certyfikaty analizy","titel_en":"ICH Q7: Produkcja, partie i certyfikaty analizy","url":"https://www.fda.gov/media/71518/download"}],"text":"Numer partii łączy konkretną fiolkę z odpowiadającym jej raportem, dzięki czemu wynik jest identyfikowalny. CoA bez jednoznacznego odniesienia do partii nie da się powiązać z rzeczywistym produktem i odpowiednio mało mówi.","text_en":"Numer partii łączy konkretną fiolkę z odpowiadającym jej raportem, dzięki czemu wynik jest identyfikowalny. CoA bez jednoznacznego odniesienia do partii nie da się powiązać z rzeczywistym produktem i odpowiednio mało mówi.","synonyme":["Partia","Lot"],"synonyme_en":["Partia","Lot"],"siehe":["coa","drittlabor"],"seiten":["charge-pruefen.html"]},{"slug":"chromatogramm","begriff":"Chromatogram","begriff_en":"Chromatogram","kategorie":"labor","kurz":"Graficzny zapis rozdziału chromatograficznego, na przykład w HPLC.","kurz_en":"Graficzny zapis rozdziału chromatograficznego, na przykład w HPLC.","quellen":[{"titel":"IUPAC Gold Book: Chromatogram","titel_en":"IUPAC Gold Book: Chromatogram","url":"https://goldbook.iupac.org/terms/view/C01071"}],"text":"Chromatogram przedstawia sygnał detektora podczas rozdziału chromatograficznego. Piki mogą się nakładać. Procenty pola powierzchni zależą od metody i detektora i nie są automatycznie procentami masowymi. Sam chromatogram nie potwierdza tożsamości peptydu.","text_en":"Chromatogram przedstawia sygnał detektora podczas rozdziału chromatograficznego. Piki mogą się nakładać. Procenty pola powierzchni zależą od metody i detektora i nie są automatycznie procentami masowymi. Sam chromatogram nie potwierdza tożsamości peptydu.","siehe":["hplc","reinheit"],"seiten":["peptid-1x1.html"]},{"slug":"cjc-1295","begriff":"CJC-1295","begriff_en":"CJC-1295","kategorie":"wirkstoff","kurz":"Syntetyczny analog GHRH badany w badaniach endokrynologicznych.","kurz_en":"Syntetyczny analog GHRH badany w badaniach endokrynologicznych.","quellen":[{"titel":"PubMed: Publikacja badawcza, PMID 16352683","titel_en":"PubMed: Publikacja badawcza, PMID 16352683","url":"https://pubmed.ncbi.nlm.nih.gov/16352683/"}],"text":"Powiązana publikacja bada długo działający analog GHRH u zdrowych dorosłych. Badany związek należy odróżniać od różnie zmodyfikowanych form oferowanych pod podobnymi nazwami handlowymi.","text_en":"Powiązana publikacja bada długo działający analog GHRH u zdrowych dorosłych. Badany związek należy odróżniać od różnie zmodyfikowanych form oferowanych pod podobnymi nazwami handlowymi.","synonyme":["CJC-1295 z DAC","DAC:GRF"],"synonyme_en":["CJC-1295 z DAC","DAC:GRF"],"link":"wirkstoffe/cjc-1295.html"},{"slug":"coa","begriff":"CoA","begriff_en":"CoA","kategorie":"labor","kurz":"CoA to raport powiązany z konkretną partią, zawierający numer partii, metodę testową i wartości takie jak czystość lub tożsamość.","kurz_en":"CoA to raport powiązany z konkretną partią, zawierający numer partii, metodę testową i wartości takie jak czystość lub tożsamość.","quellen":[{"titel":"ICH Q7: Produkcja, partie i certyfikaty analizy","titel_en":"ICH Q7: Produkcja, partie i certyfikaty analizy","url":"https://www.fda.gov/media/71518/download"}],"langform":"Certyfikat analizy","langform_en":"Certyfikat analizy","text":"O wartości CoA decyduje numer partii, ponieważ tylko on wiąże raport z konkretną fiolką. Ogólny przykładowy CoA bez powiązania z rzeczywistą partią mało mówi o faktycznym produkcie. Typowe pozycje to czystość, tożsamość, a czasem wartość endotoksyn.","text_en":"O wartości CoA decyduje numer partii, ponieważ tylko on wiąże raport z konkretną fiolką. Ogólny przykładowy CoA bez powiązania z rzeczywistą partią mało mówi o faktycznym produkcie. Typowe pozycje to czystość, tożsamość, a czasem wartość endotoksyn.","synonyme":["Certyfikat analizy","Raport z badań"],"synonyme_en":["Certyfikat analizy","Raport z badań"],"siehe":["charge","reinheit","identitaet","drittlabor"],"seiten":["charge-pruefen.html","peptid-1x1.html"]},{"slug":"datenbasis","begriff":"Zakres dowodów","begriff_en":"Zakres dowodów","kategorie":"vergleich","kurz":"Zakres dowodów pokazuje, ile z pięciu kryteriów punktowych jest udokumentowanych dla dostawcy.","kurz_en":"Zakres dowodów pokazuje, ile z pięciu kryteriów punktowych jest udokumentowanych dla dostawcy.","quellen":[{"titel":"Peptide Compass: Nasza metodologia porównawcza","titel_en":"Peptide Compass: Nasza metodologia porównawcza","url":"https://peptidkompass.com/pl/methodik.html"}],"text":"Ponieważ brakujące kryteria są pomijane przy obliczaniu wyniku, a pozostałe wagi przeliczane, już jedno udokumentowane kryterium może dać wysoką wartość. Dostawcy o różnym zakresie dowodów są więc porównywalni tylko częściowo. Liczba udokumentowanych kryteriów jest pokazana obok wyniku.","text_en":"Ponieważ brakujące kryteria są pomijane przy obliczaniu wyniku, a pozostałe wagi przeliczane, już jedno udokumentowane kryterium może dać wysoką wartość. Dostawcy o różnym zakresie dowodów są więc porównywalni tylko częściowo. Liczba udokumentowanych kryteriów jest pokazana obok wyniku.","siehe":["dokumentationsscore"],"seiten":["methodik.html"]},{"slug":"dihexa","begriff":"Dihexa","begriff_en":"Dihexa","kategorie":"wirkstoff","kurz":"Syntetyczny analog angiotensyny IV badany w modelach przedklinicznych.","kurz_en":"Syntetyczny analog angiotensyny IV badany w modelach przedklinicznych.","quellen":[{"titel":"PubMed: Publikacja badawcza, PMID 38489193","titel_en":"PubMed: Publikacja badawcza, PMID 38489193","url":"https://pubmed.ncbi.nlm.nih.gov/38489193/"},{"titel":"PubMed: redakcyjne wyrażenie zaniepokojenia dotyczące wcześniejszej publikacji","titel_en":"PubMed: redakcyjne wyrażenie zaniepokojenia dotyczące wcześniejszej publikacji","url":"https://pubmed.ncbi.nlm.nih.gov/34551989/"}],"text":"Dihexę bada się w modelach zwierzęcych. Wcześniejsza publikacja o numerze PMID 23055539 jest opatrzona wyrażeniem zaniepokojenia (Expression of Concern) i nie jest tu traktowana jako wiarygodny dowód. Dodatkowa powiązana publikacja opisuje model na szczurach i nie dowodzi stosowania u ludzi.","text_en":"Dihexę bada się w modelach zwierzęcych. Wcześniejsza publikacja o numerze PMID 23055539 jest opatrzona wyrażeniem zaniepokojenia (Expression of Concern) i nie jest tu traktowana jako wiarygodny dowód. Dodatkowa powiązana publikacja opisuje model na szczurach i nie dowodzi stosowania u ludzi.","synonyme":["PNB-0408","N-Hexanoyl-Tyr-Ile-(6)aminohexanamide"],"synonyme_en":["PNB-0408","N-Hexanoyl-Tyr-Ile-(6)aminohexanamide"],"link":"wirkstoffe/dihexa.html"},{"slug":"dokumentationsscore","begriff":"Wynik dokumentacji","begriff_en":"Wynik dokumentacji","kategorie":"vergleich","kurz":"Wynik dokumentacji pokazuje, ile zweryfikowanych twierdzeń dostawcy jest faktycznie udokumentowanych.","kurz_en":"Wynik dokumentacji pokazuje, ile zweryfikowanych twierdzeń dostawcy jest faktycznie udokumentowanych.","quellen":[{"titel":"Peptide Compass: Nasza metodologia porównawcza","titel_en":"Peptide Compass: Nasza metodologia porównawcza","url":"https://peptidkompass.com/pl/methodik.html"}],"text":"Metodologia definiuje pięć ważonych kryteriów. Obecnie do wyniku wchodzą dokumentacja laboratoryjna, informacje prawne i wysyłka; cena i asortyment pozostają bez oceny. Brakujące kryteria są pomijane, a pozostałe wagi normalizowane. Wynik nie jest pieczęcią jakości ani oceną bezpieczeństwa produktu.","text_en":"Metodologia definiuje pięć ważonych kryteriów. Obecnie do wyniku wchodzą dokumentacja laboratoryjna, informacje prawne i wysyłka; cena i asortyment pozostają bez oceny. Brakujące kryteria są pomijane, a pozostałe wagi normalizowane. Wynik nie jest pieczęcią jakości ani oceną bezpieczeństwa produktu.","siehe":["datenbasis","coa"],"seiten":["methodik.html"]},{"slug":"doppelblind","begriff":"Badanie podwójnie zaślepione","begriff_en":"Badanie podwójnie zaślepione","kategorie":"studien","kurz":"Schemat badania, w którym ani uczestnicy, ani personel nie wiedzą, kto otrzymuje substancję czynną, a kto placebo. Ogranicza nieświadome błędy systematyczne.","kurz_en":"Schemat badania, w którym ani uczestnicy, ani personel nie wiedzą, kto otrzymuje substancję czynną, a kto placebo. Ogranicza nieświadome błędy systematyczne.","quellen":[{"titel":"NCI: badanie podwójnie zaślepione","titel_en":"NCI: badanie podwójnie zaślepione","url":"https://www.cancer.gov/publications/dictionaries/cancer-terms/def/double-blind-study"}],"text":"Uczestnicy oraz zaślepieni członkowie zespołu badawczego nie znają przydziału do grup. Może to ograniczyć błędy wynikające z oczekiwań i oceny. Zaślepienie jest cechą jakości, ale nie wyklucza innych błędów metodologicznych.","text_en":"Uczestnicy oraz zaślepieni członkowie zespołu badawczego nie znają przydziału do grup. Może to ograniczyć błędy wynikające z oczekiwań i oceny. Zaślepienie jest cechą jakości, ale nie wyklucza innych błędów metodologicznych.","synonyme":["Podwójne zaślepienie","Podwójnie ślepa próba"],"synonyme_en":["Podwójne zaślepienie","Podwójnie ślepa próba"],"siehe":["rct","placebo"],"seiten":["studien.html"]},{"slug":"drittlabor","begriff":"Laboratorium strony trzeciej","begriff_en":"Laboratorium strony trzeciej","kategorie":"labor","kurz":"Laboratorium strony trzeciej to zewnętrzne laboratorium, które bada i dokumentuje próbkę niezależnie od producenta lub sklepu.","kurz_en":"Laboratorium strony trzeciej to zewnętrzne laboratorium, które bada i dokumentuje próbkę niezależnie od producenta lub sklepu.","quellen":[{"titel":"ISO/IEC 17025:2017: Kompetencje laboratoriów badawczych","titel_en":"ISO/IEC 17025:2017: Kompetencje laboratoriów badawczych","url":"https://www.iso.org/standard/66912.html"}],"text":"Jeśli CoA wskazuje laboratorium zewnętrzne, warto sprawdzić, czy jego nazwę w ogóle da się zweryfikować i czy posiada akredytację, na przykład ISO 17025. Dodatkowym sposobem niezależnego sprawdzenia wyniku jest test w ślepej próbie.","text_en":"Jeśli CoA wskazuje laboratorium zewnętrzne, warto sprawdzić, czy jego nazwę w ogóle da się zweryfikować i czy posiada akredytację, na przykład ISO 17025. Dodatkowym sposobem niezależnego sprawdzenia wyniku jest test w ślepej próbie.","synonyme":["Laboratorium zewnętrzne"],"synonyme_en":["Laboratorium zewnętrzne"],"siehe":["coa","iso-17025","blindtest"],"seiten":["methodik.html","charge-pruefen.html"]},{"slug":"dsip","begriff":"DSIP","begriff_en":"DSIP","kategorie":"wirkstoff","kurz":"Peptyd indukujący sen delta, pierwotnie opisany w doświadczeniach na zwierzętach.","kurz_en":"Peptyd indukujący sen delta, pierwotnie opisany w doświadczeniach na zwierzętach.","quellen":[{"titel":"PubMed: Publikacja badawcza, PMID 265572","titel_en":"PubMed: Publikacja badawcza, PMID 265572","url":"https://pubmed.ncbi.nlm.nih.gov/265572/"}],"text":"DSIP wyizolowano i zbadano doświadczalnie we wczesnym badaniu na królikach. Jego nazwa odzwierciedla ówczesną hipotezę badawczą. Nie dowodzi on wiarygodnego działania nasennego u ludzi.","text_en":"DSIP wyizolowano i zbadano doświadczalnie we wczesnym badaniu na królikach. Jego nazwa odzwierciedla ówczesną hipotezę badawczą. Nie dowodzi on wiarygodnego działania nasennego u ludzi.","synonyme":["Peptyd indukujący sen delta","Peptyd snu delta"],"synonyme_en":["Peptyd indukujący sen delta","Peptyd snu delta"],"link":"wirkstoffe/dsip.html"},{"slug":"ema","begriff":"EMA","begriff_en":"EMA","kategorie":"recht","kurz":"EMA to agencja UE, która koordynuje i ocenia scentralizowane procedury dopuszczenia do obrotu.","kurz_en":"EMA to agencja UE, która koordynuje i ocenia scentralizowane procedury dopuszczenia do obrotu.","quellen":[{"titel":"EMA: Oceny i decyzje o pozwoleniu","titel_en":"EMA: Oceny i decyzje o pozwoleniu","url":"https://www.ema.europa.eu/en/about-us/what-we-do/authorisation-medicines/how-ema-evaluates-medicines-human-use"}],"langform":"Europejska Agencja Leków","langform_en":"Europejska Agencja Leków","text":"Europejska Agencja Leków koordynuje ocenę naukową w scentralizowanej procedurze dopuszczenia w UE i publikuje sprawozdania z oceny. Decyzję o pozwoleniu podejmuje Komisja Europejska. Sprawozdanie EMA nie jest świadectwem badania produktów sprzedawanych przez dostawcę materiałów badawczych.","text_en":"Europejska Agencja Leków koordynuje ocenę naukową w scentralizowanej procedurze dopuszczenia w UE i publikuje sprawozdania z oceny. Decyzję o pozwoleniu podejmuje Komisja Europejska. Sprawozdanie EMA nie jest świadectwem badania produktów sprzedawanych przez dostawcę materiałów badawczych.","siehe":["zulassung","fda"]},{"slug":"endotoxin","begriff":"Endotoksyna","begriff_en":"Endotoksyna","kategorie":"labor","kurz":"Endotoksyny to składniki ściany komórkowej bakterii; ich ilość w próbce podaje się zwykle w jednostkach na miligram.","kurz_en":"Endotoksyny to składniki ściany komórkowej bakterii; ich ilość w próbce podaje się zwykle w jednostkach na miligram.","quellen":[{"titel":"FDA: Badanie pirogenów i endotoksyn","titel_en":"FDA: Badanie pirogenów i endotoksyn","url":"https://www.fda.gov/media/83477/download"}],"text":"Endotoksyny bakteryjne są składnikami bakterii Gram-ujemnych. Wyniki podaje się w jednostkach endotoksyn z określoną ilością odniesienia. Stosuje się klasyczne metody LAL oraz odczynniki rekombinowane. Badanie endotoksyn, badanie sterylności i badanie czystości chemicznej odpowiadają na różne pytania.","text_en":"Endotoksyny bakteryjne są składnikami bakterii Gram-ujemnych. Wyniki podaje się w jednostkach endotoksyn z określoną ilością odniesienia. Stosuje się klasyczne metody LAL oraz odczynniki rekombinowane. Badanie endotoksyn, badanie sterylności i badanie czystości chemicznej odpowiadają na różne pytania.","siehe":["sterilitaet","coa"],"seiten":["methodik.html"]},{"slug":"epitalon","begriff":"Epitalon","begriff_en":"Epitalon","kategorie":"wirkstoff","kurz":"Syntetyczny tetrapeptyd badany w kulturach komórkowych pod kątem aktywności telomerazy.","kurz_en":"Syntetyczny tetrapeptyd badany w kulturach komórkowych pod kątem aktywności telomerazy.","quellen":[{"titel":"PubMed: Publikacja badawcza, PMID 12937682","titel_en":"PubMed: Publikacja badawcza, PMID 12937682","url":"https://pubmed.ncbi.nlm.nih.gov/12937682/"}],"text":"Cytowana publikacja bada epithalon w hodowlach ludzkich fibroblastów. Obserwacje dotyczące telomerazy w izolowanych komórkach nie dowodzą wydłużenia życia człowieka.","text_en":"Cytowana publikacja bada epithalon w hodowlach ludzkich fibroblastów. Obserwacje dotyczące telomerazy w izolowanych komórkach nie dowodzą wydłużenia życia człowieka.","synonyme":["Epithalon","Tetrapeptyd AEDG"],"synonyme_en":["Epithalon","Tetrapeptyd AEDG"],"link":"wirkstoffe/epitalon.html"},{"slug":"fallbericht","begriff":"Opis przypadku","begriff_en":"Opis przypadku","kategorie":"studien","kurz":"Szczegółowy opis pojedynczego, często nietypowego przypadku. Daje wstępną wskazówkę, ale nie stanowi dowodu statystycznego.","kurz_en":"Szczegółowy opis pojedynczego, często nietypowego przypadku. Daje wstępną wskazówkę, ale nie stanowi dowodu statystycznego.","quellen":[{"titel":"NCI: opis przypadku","titel_en":"NCI: opis przypadku","url":"https://www.cancer.gov/publications/dictionaries/cancer-terms/def/case-report"}],"text":"Opis przypadku przedstawia obserwacje u jednej osoby lub niewielkiej grupy przypadków, często nietypową reakcję albo rzadkie zdarzenie. Może zainspirować dalsze badania, ale nie ma grupy kontrolnej ani analizy statystycznej. Sam opis przypadku nie dowodzi ogólnego efektu.","text_en":"Opis przypadku przedstawia obserwacje u jednej osoby lub niewielkiej grupy przypadków, często nietypową reakcję albo rzadkie zdarzenie. Może zainspirować dalsze badania, ale nie ma grupy kontrolnej ani analizy statystycznej. Sam opis przypadku nie dowodzi ogólnego efektu.","synonyme":["Opis przypadku"],"synonyme_en":["Opis przypadku"],"siehe":["klinische-studie","peer-review"],"seiten":["studien.html"]},{"slug":"fda","begriff":"FDA","begriff_en":"FDA","kategorie":"recht","kurz":"Agencja USA odpowiedzialna między innymi za regulację leków, żywności i wyrobów medycznych.","kurz_en":"Agencja USA odpowiedzialna między innymi za regulację leków, żywności i wyrobów medycznych.","quellen":[{"titel":"FDA: czym zajmuje się agencja i czego nie zatwierdza","titel_en":"FDA: czym zajmuje się agencja i czego nie zatwierdza","url":"https://www.fda.gov/consumers/consumer-updates/10-facts-about-what-fda-does-and-does-not-approve"}],"langform":"Amerykańska Agencja ds. Żywności i Leków","langform_en":"Amerykańska Agencja ds. Żywności i Leków","text":"Amerykańska Agencja ds. Żywności i Leków (Food and Drug Administration) reguluje między innymi leki, żywność i wyroby medyczne w Stanach Zjednoczonych. Nie każda regulowana kategoria produktów podlega zatwierdzeniu przed wprowadzeniem na rynek. Zatwierdzenie FDA dotyczy konkretnego produktu i nie jest pozwoleniem obowiązującym w UE.","text_en":"Amerykańska Agencja ds. Żywności i Leków (Food and Drug Administration) reguluje między innymi leki, żywność i wyroby medyczne w Stanach Zjednoczonych. Nie każda regulowana kategoria produktów podlega zatwierdzeniu przed wprowadzeniem na rynek. Zatwierdzenie FDA dotyczy konkretnego produktu i nie jest pozwoleniem obowiązującym w UE.","siehe":["zulassung","ema"]},{"slug":"fragment","begriff":"Fragment","begriff_en":"Fragment","kategorie":"grundlagen","kurz":"Krótki odcinek większego endogennego peptydu lub białka, odtworzony syntetycznie.","kurz_en":"Krótki odcinek większego endogennego peptydu lub białka, odtworzony syntetycznie.","quellen":[{"titel":"Purves et al.: Neuroprzekaźniki peptydowe","titel_en":"Purves et al.: Neuroprzekaźniki peptydowe","url":"https://www.ncbi.nlm.nih.gov/books/NBK10873/"}],"text":"Fragment obejmuje tylko część łańcucha aminokwasów peptydu lub białka, a nie całą sekwencję. Takie częściowe sekwencje syntetyzuje się, aby sprawdzić, która część łańcucha odpowiada za określone właściwości, na przykład wiązanie z receptorem. Znanym przykładem jest tymozyna alfa-1, fragment większego białka prekursorowego.","text_en":"Fragment obejmuje tylko część łańcucha aminokwasów peptydu lub białka, a nie całą sekwencję. Takie częściowe sekwencje syntetyzuje się, aby sprawdzić, która część łańcucha odpowiada za określone właściwości, na przykład wiązanie z receptorem. Znanym przykładem jest tymozyna alfa-1, fragment większego białka prekursorowego.","siehe":["peptid","analogon","sequenz"]},{"slug":"gegenion","begriff":"Przeciwjon","begriff_en":"Przeciwjon","kategorie":"labor","kurz":"Przeciwjon to sól towarzysząca peptydowi, zwykle trifluorooctan (TFA) lub octan, pozostałość po produkcji.","kurz_en":"Przeciwjon to sól towarzysząca peptydowi, zwykle trifluorooctan (TFA) lub octan, pozostałość po produkcji.","quellen":[{"titel":"Hoofnagle et al. (2016): Analiza peptydów i postępowanie w laboratorium","titel_en":"Hoofnagle et al. (2016): Analiza peptydów i postępowanie w laboratorium","url":"https://pubmed.ncbi.nlm.nih.gov/26719571/"}],"text":"Przeciwjon równoważy ładunek elektryczny. Przeciwjony mogą zwiększać masę próbki, nie będąc częścią sekwencji aminokwasów peptydu.","text_en":"Przeciwjon równoważy ładunek elektryczny. Przeciwjony mogą zwiększać masę próbki, nie będąc częścią sekwencji aminokwasów peptydu.","siehe":["peptidgehalt","reinheit"],"seiten":["methodik.html"]},{"slug":"ghk-cu","begriff":"GHK-Cu","begriff_en":"GHK-Cu","kategorie":"wirkstoff","kurz":"Kompleks tripeptydu GHK z miedzią badany w różnych modelach przedklinicznych.","kurz_en":"Kompleks tripeptydu GHK z miedzią badany w różnych modelach przedklinicznych.","quellen":[{"titel":"PubMed: publikacja badawcza, PMID 40672369","titel_en":"PubMed: publikacja badawcza, PMID 40672369","url":"https://pubmed.ncbi.nlm.nih.gov/40672369/"}],"text":"GHK to skrót od glicylo-histydylo-lizyny. Powiązane badanie analizuje kompleks z miedzią w eksperymentalnym modelu zapalenia jelita grubego oraz w testach komórkowych. Nie jest to dowód kliniczny dla pielęgnacji skóry ani innych zastosowań.","text_en":"GHK to skrót od glicylo-histydylo-lizyny. Powiązane badanie analizuje kompleks z miedzią w eksperymentalnym modelu zapalenia jelita grubego oraz w testach komórkowych. Nie jest to dowód kliniczny dla pielęgnacji skóry ani innych zastosowań.","synonyme":["Glicylo-L-histydylo-L-lizyna z miedzią","Miedziowy tripeptyd-1"],"synonyme_en":["Glicylo-L-histydylo-L-lizyna z miedzią","Miedziowy tripeptyd-1"],"link":"wirkstoffe/ghk-cu.html"},{"slug":"ghrh","begriff":"GHRH","begriff_en":"GHRH","kategorie":"klassen","kurz":"GHRH to hormon podwzgórza, który pobudza przysadkę do uwalniania hormonu wzrostu.","kurz_en":"GHRH to hormon podwzgórza, który pobudza przysadkę do uwalniania hormonu wzrostu.","quellen":[{"titel":"Teichman et al. (2006): Badania nad analogiem GHRH","titel_en":"Teichman et al. (2006): Badania nad analogiem GHRH","url":"https://pubmed.ncbi.nlm.nih.gov/16352683/"}],"langform":"Hormon uwalniający hormon wzrostu","langform_en":"Hormon uwalniający hormon wzrostu","text":"Hormon uwalniający hormon wzrostu to peptyd podwzgórza, który dociera układem wrotnym przysadki do przysadki mózgowej i pobudza komórki somatotropowe do uwalniania hormonu wzrostu. Jest częścią osi hormonu wzrostu i stanowi przeciwwagę dla własnego hormonu hamującego organizmu, somatostatyny. Kilka syntetycznych analogów GHRH wiąże ten sam receptor i jest badanych lub stosowanych w tym kontekście.","text_en":"Hormon uwalniający hormon wzrostu to peptyd podwzgórza, który dociera układem wrotnym przysadki do przysadki mózgowej i pobudza komórki somatotropowe do uwalniania hormonu wzrostu. Jest częścią osi hormonu wzrostu i stanowi przeciwwagę dla własnego hormonu hamującego organizmu, somatostatyny. Kilka syntetycznych analogów GHRH wiąże ten sam receptor i jest badanych lub stosowanych w tym kontekście.","synonyme":["Somatoliberyna"],"synonyme_en":["Somatoliberyna"],"siehe":["ghrp","wachstumshormon","rezeptor"],"wirkstoffe":["cjc-1295","tesamorelin","sermorelin"],"seiten":["peptid-1x1.html"]},{"slug":"ghrp","begriff":"GHRP","begriff_en":"GHRP","kategorie":"klassen","kurz":"GHRP to syntetyczne peptydy, które wywołują uwalnianie hormonu wzrostu przez receptor greliny.","kurz_en":"GHRP to syntetyczne peptydy, które wywołują uwalnianie hormonu wzrostu przez receptor greliny.","quellen":[{"titel":"Raun et al. (1998): Rola receptora w działaniu GHRP","titel_en":"Raun et al. (1998): Rola receptora w działaniu GHRP","url":"https://pubmed.ncbi.nlm.nih.gov/9849822/"}],"langform":"Peptyd uwalniający hormon wzrostu","langform_en":"Peptyd uwalniający hormon wzrostu","text":"Peptydy uwalniające hormon wzrostu to klasa syntetycznych peptydów, które wiążą receptor greliny (GHS-R) i w ten sposób wywołują uwalnianie hormonu wzrostu z przysadki. W przeciwieństwie do analogów GHRH korzystają z odrębnego szlaku sygnałowego i w badaniach często łączy się je z analogami GHRH. Receptor greliny uczestniczy także w regulacji głodu i apetytu.","text_en":"Peptydy uwalniające hormon wzrostu to klasa syntetycznych peptydów, które wiążą receptor greliny (GHS-R) i w ten sposób wywołują uwalnianie hormonu wzrostu z przysadki. W przeciwieństwie do analogów GHRH korzystają z odrębnego szlaku sygnałowego i w badaniach często łączy się je z analogami GHRH. Receptor greliny uczestniczy także w regulacji głodu i apetytu.","synonyme":["Sekretagogi GH","Sekretagogi hormonu wzrostu"],"synonyme_en":["Sekretagogi GH","Sekretagogi hormonu wzrostu"],"siehe":["ghrh","wachstumshormon","rezeptor"],"wirkstoffe":["ipamorelin","hexarelin"],"seiten":["peptid-1x1.html"]},{"slug":"gip","begriff":"GIP","begriff_en":"GIP","kategorie":"klassen","kurz":"GIP to hormon jelitowy, który reguluje uwalnianie insuliny po posiłkach bogatych w węglowodany.","kurz_en":"GIP to hormon jelitowy, który reguluje uwalnianie insuliny po posiłkach bogatych w węglowodany.","quellen":[{"titel":"NIDDK: Podstawy badań nad inkretynami","titel_en":"NIDDK: Podstawy badań nad inkretynami","url":"https://www.niddk.nih.gov/news/archive/2021/story-discovery-medications-diabetes-obesity-emerged-research-pancreatic-hormone"}],"langform":"Glukozależny polipeptyd insulinotropowy","langform_en":"Glukozależny polipeptyd insulinotropowy","text":"Glukozależny polipeptyd insulinotropowy to obok GLP-1 drugi główny hormon inkretynowy. Komórki K w górnej części jelita cienkiego uwalniają go po posiłku, a on wiąże receptor GIP, regulując uwalnianie insuliny. Uczestniczy też w metabolizmie tłuszczów. Kilka nowszych związków stosowanych w cukrzycy i otyłości łączy agonizm receptora GIP z agonizmem receptora GLP-1.","text_en":"Glukozależny polipeptyd insulinotropowy to obok GLP-1 drugi główny hormon inkretynowy. Komórki K w górnej części jelita cienkiego uwalniają go po posiłku, a on wiąże receptor GIP, regulując uwalnianie insuliny. Uczestniczy też w metabolizmie tłuszczów. Kilka nowszych związków stosowanych w cukrzycy i otyłości łączy agonizm receptora GIP z agonizmem receptora GLP-1.","siehe":["glp-1","inkretin","rezeptor"],"wirkstoffe":["tirzepatid","retatrutid"],"seiten":["peptid-1x1.html"]},{"slug":"glp-1","begriff":"GLP-1","begriff_en":"GLP-1","kategorie":"klassen","kurz":"GLP-1 to hormon jelitowy uwalniany po jedzeniu, który reguluje uwalnianie insuliny.","kurz_en":"GLP-1 to hormon jelitowy uwalniany po jedzeniu, który reguluje uwalnianie insuliny.","quellen":[{"titel":"NIDDK: Podstawy badań nad inkretynami","titel_en":"NIDDK: Podstawy badań nad inkretynami","url":"https://www.niddk.nih.gov/news/archive/2021/story-discovery-medications-diabetes-obesity-emerged-research-pancreatic-hormone"}],"langform":"Peptyd glukagonopodobny 1","langform_en":"Peptyd glukagonopodobny 1","text":"Peptyd glukagonopodobny 1 to hormon inkretynowy uwalniany po posiłku przez komórki L jelita cienkiego. Wiąże receptor GLP-1, reguluje uwalnianie insuliny, spowalnia opróżnianie żołądka i uczestniczy w sygnalizacji sytości w mózgu. Kilku syntetycznych agonistów receptora GLP-1 działa na ten układ, a niektórzy z nich są zatwierdzeni jako leki.","text_en":"Peptyd glukagonopodobny 1 to hormon inkretynowy uwalniany po posiłku przez komórki L jelita cienkiego. Wiąże receptor GLP-1, reguluje uwalnianie insuliny, spowalnia opróżnianie żołądka i uczestniczy w sygnalizacji sytości w mózgu. Kilku syntetycznych agonistów receptora GLP-1 działa na ten układ, a niektórzy z nich są zatwierdzeni jako leki.","synonyme":["Peptyd glukagonopodobny-1"],"synonyme_en":["Peptyd glukagonopodobny-1"],"siehe":["gip","inkretin","rezeptor","agonist"],"wirkstoffe":["semaglutid","tirzepatid","retatrutid","survodutid"],"seiten":["peptid-1x1.html"]},{"slug":"gmp","begriff":"GMP","begriff_en":"GMP","kategorie":"recht","kurz":"GMP to uznany standard jakości w produkcji produktów leczniczych i podobnych wyrobów.","kurz_en":"GMP to uznany standard jakości w produkcji produktów leczniczych i podobnych wyrobów.","quellen":[{"titel":"ICH Q7: Produkcja, partie i certyfikaty analizy","titel_en":"ICH Q7: Produkcja, partie i certyfikaty analizy","url":"https://www.fda.gov/media/71518/download"}],"langform":"Dobra Praktyka Wytwarzania","langform_en":"Dobra Praktyka Wytwarzania","text":"Dobra Praktyka Wytwarzania obejmuje wymagania dotyczące obiektów, procesów, dokumentacji i identyfikowalności w produkcji. GMP jest obowiązkowa głównie dla produktów leczniczych dopuszczonych do obrotu. Deklaracja GMP producenta nie zastępuje niezależnych dowodów, takich jak publiczne CoA, i obowiązuje tylko w zakresie, w jakim jest udokumentowana.","text_en":"Dobra Praktyka Wytwarzania obejmuje wymagania dotyczące obiektów, procesów, dokumentacji i identyfikowalności w produkcji. GMP jest obowiązkowa głównie dla produktów leczniczych dopuszczonych do obrotu. Deklaracja GMP producenta nie zastępuje niezależnych dowodów, takich jak publiczne CoA, i obowiązuje tylko w zakresie, w jakim jest udokumentowana.","siehe":["zulassung","coa"],"seiten":["methodik.html"]},{"slug":"halbwertszeit","begriff":"Czas półtrwania","begriff_en":"Czas półtrwania","kategorie":"grundlagen","kurz":"Czas potrzebny na spadek stężenia substancji w organizmie o połowę.","kurz_en":"Czas potrzebny na spadek stężenia substancji w organizmie o połowę.","quellen":[{"titel":"NCBI Bookshelf: Farmakokinetyka","titel_en":"NCBI Bookshelf: Farmakokinetyka","url":"https://www.ncbi.nlm.nih.gov/books/NBK557744/"}],"text":"Czas półtrwania opisuje, po jakim czasie stężenie peptydu we krwi spada do połowy wartości początkowej. Mierzy się go w badaniach farmakokinetycznych i znacznie różni się między poszczególnymi peptydami, częściowo w zależności od tego, jak szybko endogenne enzymy rozkładają łańcuch w procesie proteolizy. Krótszy czas półtrwania oznacza szybszy rozkład w porównaniu z dłuższym.","text_en":"Czas półtrwania opisuje, po jakim czasie stężenie peptydu we krwi spada do połowy wartości początkowej. Mierzy się go w badaniach farmakokinetycznych i znacznie różni się między poszczególnymi peptydami, częściowo w zależności od tego, jak szybko endogenne enzymy rozkładają łańcuch w procesie proteolizy. Krótszy czas półtrwania oznacza szybszy rozkład w porównaniu z dłuższym.","siehe":["proteolyse","bioverfuegbarkeit"]},{"slug":"hexarelin","begriff":"Hexarelin","begriff_en":"Hexarelin","kategorie":"wirkstoff","kurz":"Syntetyczny peptyd badany w badaniach osi hormonu wzrostu.","kurz_en":"Syntetyczny peptyd badany w badaniach osi hormonu wzrostu.","quellen":[{"titel":"PubMed: Publikacja badawcza, PMID 7910650","titel_en":"PubMed: Publikacja badawcza, PMID 7910650","url":"https://pubmed.ncbi.nlm.nih.gov/7910650/"}],"text":"Cytowana publikacja źródłowa opisuje hexarelin jako peptyd syntetyczny i bada uwalnianie hormonu wzrostu u szczurów. Takie wyniki z modeli nie dowodzą bezpieczeństwa stosowania u ludzi.","text_en":"Cytowana publikacja źródłowa opisuje hexarelin jako peptyd syntetyczny i bada uwalnianie hormonu wzrostu u szczurów. Takie wyniki z modeli nie dowodzą bezpieczeństwa stosowania u ludzi.","link":"wirkstoffe/hexarelin.html"},{"slug":"hplc","begriff":"HPLC","begriff_en":"HPLC","kategorie":"labor","kurz":"HPLC to standardowa metoda analityczna służąca do określania czystości próbki peptydu w procentach.","kurz_en":"HPLC to standardowa metoda analityczna służąca do określania czystości próbki peptydu w procentach.","quellen":[{"titel":"FDA: Analiza złożonych mieszanin i peptydów","titel_en":"FDA: Analiza złożonych mieszanin i peptydów","url":"https://www.fda.gov/industry/generic-drug-user-fee-amendments/fys-2013-2017-regulatory-science-report-complex-mixtures-and-peptides"}],"langform":"Wysokosprawna chromatografia cieczowa","langform_en":"Wysokosprawna chromatografia cieczowa","text":"Metoda rozdziela próbkę na składniki i mierzy każdy z nich, tworząc chromatogram z jednym pikiem na składnik. Pole głównego piku daje podaną wartość czystości. Sama HPLC nic nie mówi o tożsamości; do tego potrzebna jest również spektrometria mas.","text_en":"Metoda rozdziela próbkę na składniki i mierzy każdy z nich, tworząc chromatogram z jednym pikiem na składnik. Pole głównego piku daje podaną wartość czystości. Sama HPLC nic nie mówi o tożsamości; do tego potrzebna jest również spektrometria mas.","synonyme":["Wysokosprawna chromatografia cieczowa"],"synonyme_en":["Wysokosprawna chromatografia cieczowa"],"siehe":["reinheit","chromatogramm","massenspektrometrie"],"seiten":["methodik.html","peptid-1x1.html"]},{"slug":"hwg","begriff":"HWG","begriff_en":"HWG","kategorie":"recht","kurz":"HWG reguluje w Niemczech reklamę produktów leczniczych i metod terapeutycznych skierowaną do opinii publicznej.","kurz_en":"HWG reguluje w Niemczech reklamę produktów leczniczych i metod terapeutycznych skierowaną do opinii publicznej.","quellen":[{"titel":"Niemiecka ustawa o reklamie w ochronie zdrowia, tekst urzędowy","titel_en":"Niemiecka ustawa o reklamie w ochronie zdrowia, tekst urzędowy","url":"https://www.gesetze-im-internet.de/heilmwerbg/"}],"langform":"Ustawa o reklamie produktów leczniczych (Heilmittelwerbegesetz)","langform_en":"Ustawa o reklamie produktów leczniczych (Heilmittelwerbegesetz)","text":"Niemiecka ustawa o reklamie produktów leczniczych ogranicza sposób, w jaki można publicznie opisywać produkty lecznicze i metody leczenia, w tym twierdzenia dotyczące chorób lub stosowania u ludzi. Dlatego Peptide Compass opisuje substancje wyłącznie w kategoriach wyników badań i nie formułuje twierdzeń o działaniu w organizmie czytelnika.","text_en":"Niemiecka ustawa o reklamie produktów leczniczych ogranicza sposób, w jaki można publicznie opisywać produkty lecznicze i metody leczenia, w tym twierdzenia dotyczące chorób lub stosowania u ludzi. Dlatego Peptide Compass opisuje substancje wyłącznie w kategoriach wyników badań i nie formułuje twierdzeń o działaniu w organizmie czytelnika.","siehe":["arzneimittel"],"seiten":["methodik.html"]},{"slug":"identitaet","begriff":"Tożsamość","begriff_en":"Tożsamość","kategorie":"labor","kurz":"Tożsamość, potwierdzona spektrometrią mas, weryfikuje, że próbka rzeczywiście zawiera podany peptyd.","kurz_en":"Tożsamość, potwierdzona spektrometrią mas, weryfikuje, że próbka rzeczywiście zawiera podany peptyd.","quellen":[{"titel":"FDA: Analiza złożonych mieszanin i peptydów","titel_en":"FDA: Analiza złożonych mieszanin i peptydów","url":"https://www.fda.gov/industry/generic-drug-user-fee-amendments/fys-2013-2017-regulatory-science-report-complex-mixtures-and-peptides"}],"text":"Wykazuje się ją zwykle metodą LC-MS, czyli połączeniem chromatografii cieczowej ze spektrometrią mas, która mierzy masę cząsteczkową. Czystość i tożsamość to dwie osobne wartości, a kompletny CoA podaje obie. Sama czystość nie dowodzi, jaka cząsteczka jest faktycznie obecna.","text_en":"Wykazuje się ją zwykle metodą LC-MS, czyli połączeniem chromatografii cieczowej ze spektrometrią mas, która mierzy masę cząsteczkową. Czystość i tożsamość to dwie osobne wartości, a kompletny CoA podaje obie. Sama czystość nie dowodzi, jaka cząsteczka jest faktycznie obecna.","siehe":["massenspektrometrie","reinheit","coa"],"seiten":["peptid-1x1.html"]},{"slug":"igf-1","begriff":"IGF-1","begriff_en":"IGF-1","kategorie":"klassen","kurz":"IGF-1 to hormon wytwarzany głównie w wątrobie w odpowiedzi na hormon wzrostu.","kurz_en":"IGF-1 to hormon wytwarzany głównie w wątrobie w odpowiedzi na hormon wzrostu.","quellen":[{"titel":"NIDDK: Hormon wzrostu i IGF-1","titel_en":"NIDDK: Hormon wzrostu i IGF-1","url":"https://www.niddk.nih.gov/health-information/endocrine-diseases/acromegaly"}],"langform":"Insulinopodobny czynnik wzrostu 1","langform_en":"Insulinopodobny czynnik wzrostu 1","text":"Insulinopodobny czynnik wzrostu 1 powstaje głównie w wątrobie, pod wpływem wiązania hormonu wzrostu z komórkami wątroby, i krąży we krwi w dużej mierze związany z białkami nośnikowymi. Wiąże receptor IGF-1 i pośredniczy w dużej części działania hormonu wzrostu na mięśnie, kości i tkankę łączną. Analog IGF-1 o wydłużonym czasie półtrwania jest wykorzystywany w badaniach jako samodzielne narzędzie, niezależne od własnej regulacji organizmu przez hormon wzrostu.","text_en":"Insulinopodobny czynnik wzrostu 1 powstaje głównie w wątrobie, pod wpływem wiązania hormonu wzrostu z komórkami wątroby, i krąży we krwi w dużej mierze związany z białkami nośnikowymi. Wiąże receptor IGF-1 i pośredniczy w dużej części działania hormonu wzrostu na mięśnie, kości i tkankę łączną. Analog IGF-1 o wydłużonym czasie półtrwania jest wykorzystywany w badaniach jako samodzielne narzędzie, niezależne od własnej regulacji organizmu przez hormon wzrostu.","synonyme":["Somatomedin C"],"synonyme_en":["Somatomedin C"],"siehe":["wachstumshormon","ghrh","rezeptor"],"wirkstoffe":["igf-1-lr3"],"seiten":["peptid-1x1.html"]},{"slug":"igf-1-lr3","begriff":"IGF-1 LR3","begriff_en":"IGF-1 LR3","kategorie":"wirkstoff","kurz":"Zmodyfikowany analog IGF-1 badany w modelach przedklinicznych.","kurz_en":"Zmodyfikowany analog IGF-1 badany w modelach przedklinicznych.","quellen":[{"titel":"PubMed: Publikacja badawcza, PMID 7561636","titel_en":"PubMed: Publikacja badawcza, PMID 7561636","url":"https://pubmed.ncbi.nlm.nih.gov/7561636/"}],"text":"Cytowana publikacja bada Long R3 IGF-I u świnek morskich i opisuje zmniejszone powinowactwo do białek wiążących IGF. Wyniki dla tej zmodyfikowanej formy nie są wymienne z wynikami dla endogennego IGF-1.","text_en":"Cytowana publikacja bada Long R3 IGF-I u świnek morskich i opisuje zmniejszone powinowactwo do białek wiążących IGF. Wyniki dla tej zmodyfikowanej formy nie są wymienne z wynikami dla endogennego IGF-1.","synonyme":["Long R3 IGF-1","LR3-IGF-1","IGF-1 Long R3"],"synonyme_en":["Long R3 IGF-1","LR3-IGF-1","IGF-1 Long R3"],"link":"wirkstoffe/igf-1-lr3.html"},{"slug":"in-vitro","begriff":"In vitro","begriff_en":"In vitro","kategorie":"studien","kurz":"Badanie poza żywym organizmem, zwykle na hodowlach komórkowych. Nie mówi nic o działaniu u ludzi.","kurz_en":"Badanie poza żywym organizmem, zwykle na hodowlach komórkowych. Nie mówi nic o działaniu u ludzi.","quellen":[{"titel":"NCI: in vitro","titel_en":"NCI: in vitro","url":"https://www.cancer.gov/publications/dictionaries/cancer-terms/def/in-vitro"}],"text":"Badania in vitro dotyczą izolowanych komórek lub cząsteczek w kontrolowanych warunkach, na przykład na szalce Petriego. Mogą pokazać wczesne efekty biochemiczne, ale środowisko komórkowe nie zastępuje całego organizmu. Takie dane to wyłącznie badania laboratoryjne i nie przekładają się na ludzi.","text_en":"Badania in vitro dotyczą izolowanych komórek lub cząsteczek w kontrolowanych warunkach, na przykład na szalce Petriego. Mogą pokazać wczesne efekty biochemiczne, ale środowisko komórkowe nie zastępuje całego organizmu. Takie dane to wyłącznie badania laboratoryjne i nie przekładają się na ludzi.","synonyme":["in vitro"],"synonyme_en":["in vitro"],"siehe":["in-vivo","praeklinisch","tiermodell"],"seiten":["studien.html"]},{"slug":"in-vivo","begriff":"in vivo","begriff_en":"in vivo","kategorie":"studien","kurz":"Badanie w żywym organizmie. Sam termin nie rozróżnia danych zwierzęcych od ludzkich.","kurz_en":"Badanie w żywym organizmie. Sam termin nie rozróżnia danych zwierzęcych od ludzkich.","quellen":[{"titel":"NCI: in vivo","titel_en":"NCI: in vivo","url":"https://www.cancer.gov/publications/dictionaries/cancer-terms/def/in-vivo"}],"text":"In vivo oznacza, że badanie odbywa się w żywym organizmie. Może to być zwierzę lub człowiek. Wyniki badań muszą zatem identyfikować badany model. Wyniki na zwierzętach nie mogą być bezpośrednio przenoszone na ludzi.","text_en":"In vivo oznacza, że badanie odbywa się w żywym organizmie. Może to być zwierzę lub człowiek. Wyniki badań muszą zatem identyfikować badany model. Wyniki na zwierzętach nie mogą być bezpośrednio przenoszone na ludzi.","synonyme":["in vivo"],"synonyme_en":["in vivo"],"siehe":["in-vitro","tiermodell","praeklinisch"],"seiten":["studien.html"]},{"slug":"inkretin","begriff":"Inkretyna","begriff_en":"Inkretyna","kategorie":"klassen","kurz":"Inkretyny to hormony jelitowe uwalniane po jedzeniu, które są zaangażowane w regulację uwalniania insuliny.","kurz_en":"Inkretyny to hormony jelitowe uwalniane po jedzeniu, które są zaangażowane w regulację uwalniania insuliny.","quellen":[{"titel":"NIDDK: Podstawy badań nad inkretynami","titel_en":"NIDDK: Podstawy badań nad inkretynami","url":"https://www.niddk.nih.gov/news/archive/2021/story-discovery-medications-diabetes-obesity-emerged-research-pancreatic-hormone"}],"text":"Inkretyny to klasa hormonów jelitowych, do której należą GLP-1 i GIP. Są uwalniane ze specjalnych komórek jelita po posiłku i wiążą się ze swoimi receptorami na komórkach beta trzustki. Dzięki temu mechanizmowi uwalnianie insuliny po doustnym przyjęciu glukozy jest większe niż po dożylnym podaniu takiej samej ilości; zjawisko to nazywa się efektem inkretynowym. Kilka dopuszczonych do obrotu i badanych leków naśladuje ten szlak.","text_en":"Inkretyny to klasa hormonów jelitowych, do której należą GLP-1 i GIP. Są uwalniane ze specjalnych komórek jelita po posiłku i wiążą się ze swoimi receptorami na komórkach beta trzustki. Dzięki temu mechanizmowi uwalnianie insuliny po doustnym przyjęciu glukozy jest większe niż po dożylnym podaniu takiej samej ilości; zjawisko to nazywa się efektem inkretynowym. Kilka dopuszczonych do obrotu i badanych leków naśladuje ten szlak.","synonyme":["Hormony inkretynowe"],"synonyme_en":["Hormony inkretynowe"],"siehe":["glp-1","gip","peptidhormon","rezeptor"],"wirkstoffe":["semaglutid","tirzepatid","retatrutid","survodutid"],"seiten":["peptid-1x1.html"]},{"slug":"ipamorelin","begriff":"Ipamorelin","begriff_en":"Ipamorelin","kategorie":"wirkstoff","kurz":"Syntetyczny pentapeptyd badany w badaniach uwalniania hormonu wzrostu.","kurz_en":"Syntetyczny pentapeptyd badany w badaniach uwalniania hormonu wzrostu.","quellen":[{"titel":"PubMed: Publikacja badawcza, PMID 9849822","titel_en":"PubMed: Publikacja badawcza, PMID 9849822","url":"https://pubmed.ncbi.nlm.nih.gov/9849822/"}],"text":"Publikacja opisująca rozwój tego związku przedstawia pentapeptyd i bada udział receptorów oraz uwalnianie hormonu w modelach komórkowych i zwierzęcych. Tych wyników nie można ogólnie przenosić na ludzi.","text_en":"Publikacja opisująca rozwój tego związku przedstawia pentapeptyd i bada udział receptorów oraz uwalnianie hormonu w modelach komórkowych i zwierzęcych. Tych wyników nie można ogólnie przenosić na ludzi.","synonyme":["NNC 26-0161"],"synonyme_en":["NNC 26-0161"],"link":"wirkstoffe/ipamorelin.html"},{"slug":"iso-17025","begriff":"ISO 17025","begriff_en":"ISO 17025","kategorie":"labor","kurz":"ISO 17025 to międzynarodowy standard dla technicznej kompetencji laboratoriów testujących i kalibrujących.","kurz_en":"ISO 17025 to międzynarodowy standard dla technicznej kompetencji laboratoriów testujących i kalibrujących.","quellen":[{"titel":"ISO/IEC 17025:2017: Kompetencje laboratoriów badawczych","titel_en":"ISO/IEC 17025:2017: Kompetencje laboratoriów badawczych","url":"https://www.iso.org/standard/66912.html"}],"langform":"ISO/IEC 17025","langform_en":"ISO/IEC 17025","text":"Akredytacja zgodnie z tą normą oznacza, że procedury, wyposażenie i personel laboratorium zostały niezależnie ocenione. Jest to wskaźnik jakości samego laboratorium, a nie gwarancja dla żadnego konkretnego wyniku CoA.","text_en":"Akredytacja zgodnie z tą normą oznacza, że procedury, wyposażenie i personel laboratorium zostały niezależnie ocenione. Jest to wskaźnik jakości samego laboratorium, a nie gwarancja dla żadnego konkretnego wyniku CoA.","siehe":["drittlabor","coa"],"seiten":["methodik.html"]},{"slug":"internationale-einheit","begriff":"IU","begriff_en":"IU","kategorie":"handhabung","kurz":"Jednostka międzynarodowa mierzy biologiczną moc substancji względem wzorca odniesienia, a nie jej masę.","kurz_en":"Jednostka międzynarodowa mierzy biologiczną moc substancji względem wzorca odniesienia, a nie jej masę.","quellen":[{"titel":"WHO: Biologiczne wzorce odniesienia","titel_en":"WHO: Biologiczne wzorce odniesienia","url":"https://www.who.int/activities/providing-international-biological-reference-standards"}],"langform":"Jednostka międzynarodowa","langform_en":"Jednostka międzynarodowa","text":"W przypadku substancji takich jak hormon wzrostu sama masa nie opisuje ilości w sposób miarodajny, ponieważ różne partie mogą przy tej samej masie różnić się czystością. Jednostka międzynarodowa określa ilość w odniesieniu do zdefiniowanego preparatu wzorcowego WHO. Jeden miligram jednego hormonu nie jest więc automatycznie równy takiej samej liczbie jednostek co jeden miligram innego preparatu.","text_en":"W przypadku substancji takich jak hormon wzrostu sama masa nie opisuje ilości w sposób miarodajny, ponieważ różne partie mogą przy tej samej masie różnić się czystością. Jednostka międzynarodowa określa ilość w odniesieniu do zdefiniowanego preparatu wzorcowego WHO. Jeden miligram jednego hormonu nie jest więc automatycznie równy takiej samej liczbie jednostek co jeden miligram innego preparatu.","synonyme":["IE"],"synonyme_en":["IU"],"siehe":["milligramm-mikrogramm","wachstumshormon"]},{"slug":"kisspeptin","begriff":"Kisspeptyna-10","begriff_en":"Kisspeptyna-10","kategorie":"wirkstoff","kurz":"Rodzina peptydów badana w badaniach endokrynologicznych; ten katalog koncentruje się na kisspeptynie-10.","kurz_en":"Rodzina peptydów badana w badaniach endokrynologicznych; ten katalog koncentruje się na kisspeptynie-10.","quellen":[{"titel":"PubMed: Publikacja badawcza, PMID 21632807","titel_en":"PubMed: Publikacja badawcza, PMID 21632807","url":"https://pubmed.ncbi.nlm.nih.gov/21632807/"}],"text":"Cytowane badanie bada kisspeptynę-10 u mężczyzn. Inne izoformy, takie jak kisspeptyna-54, należy rozpatrywać osobno. Ogólny termin kisspeptyna nie określa w pełni badanej formy.","text_en":"Cytowane badanie bada kisspeptynę-10 u mężczyzn. Inne izoformy, takie jak kisspeptyna-54, należy rozpatrywać osobno. Ogólny termin kisspeptyna nie określa w pełni badanej formy.","synonyme":["Metastin (45-54)","KP-10"],"synonyme_en":["Metastin (45-54)","KP-10"],"link":"wirkstoffe/kisspeptin.html"},{"slug":"klinische-studie","begriff":"Badanie kliniczne","begriff_en":"Badanie kliniczne","kategorie":"studien","kurz":"Badanie z udziałem ludzi, zwykle zorganizowane w fazach I–III. Najbardziej informatywny typ badania dla ludzi.","kurz_en":"Badanie z udziałem ludzi, zwykle zorganizowane w fazach I–III. Najbardziej informatywny typ badania dla ludzi.","quellen":[{"titel":"NCI: badanie kliniczne","titel_en":"NCI: badanie kliniczne","url":"https://www.cancer.gov/publications/dictionaries/cancer-terms/def/clinical-trial"}],"text":"Badanie kliniczne dotyczy pytania medycznego z udziałem ludzi. Badania różnią się liczebnością, grupami porównawczymi, zaślepieniem i mierzonymi wynikami. Te cechy pomagają ocenić, jak wiarygodny jest wynik. Sama rejestracja lub publikacja badania nie przesądza ani o dopuszczeniu do obrotu, ani o jakości produktu sklepowego.","text_en":"Badanie kliniczne dotyczy pytania medycznego z udziałem ludzi. Badania różnią się liczebnością, grupami porównawczymi, zaślepieniem i mierzonymi wynikami. Te cechy pomagają ocenić, jak wiarygodny jest wynik. Sama rejestracja lub publikacja badania nie przesądza ani o dopuszczeniu do obrotu, ani o jakości produktu sklepowego.","synonyme":["Badanie kliniczne"],"synonyme_en":["Badanie kliniczne"],"siehe":["studienphasen","rct","placebo","Podwójnie ślepa próba"],"seiten":["studien.html"]},{"slug":"konzentration","begriff":"Stężenie","begriff_en":"Stężenie","kategorie":"handhabung","kurz":"Stężenie określa, ile substancji jest rozpuszczone w danej objętości cieczy, zwykle w mg na ml.","kurz_en":"Stężenie określa, ile substancji jest rozpuszczone w danej objętości cieczy, zwykle w mg na ml.","quellen":[{"titel":"IUPAC Gold Book: Stężenie masowe","titel_en":"IUPAC Gold Book: Stężenie masowe","url":"https://goldbook.iupac.org/terms/view/M03713"}],"text":"Stężenie masowe odnosi masę określonej substancji do objętości końcowego roztworu, na przykład w mg/ml. Masa proszku i rzeczywista masa peptydu mogą się różnić. Ta wartość opisuje skład, a nie zastosowanie.","text_en":"Stężenie masowe odnosi masę określonej substancji do objętości końcowego roztworu, na przykład w mg/ml. Masa proszku i rzeczywista masa peptydu mogą się różnić. Ta wartość opisuje skład, a nie zastosowanie.","siehe":["rekonstitution","milligramm-mikrogramm","aliquot"]},{"slug":"kpv","begriff":"KPV","begriff_en":"KPV","kategorie":"wirkstoff","kurz":"Tripeptyd pochodzący od melanokortyn, badany w przedklinicznych modelach stanu zapalnego.","kurz_en":"Tripeptyd pochodzący od melanokortyn, badany w przedklinicznych modelach stanu zapalnego.","quellen":[{"titel":"PubMed: Publikacja badawcza, PMID 18092346","titel_en":"PubMed: Publikacja badawcza, PMID 18092346","url":"https://pubmed.ncbi.nlm.nih.gov/18092346/"}],"text":"KPV to skrót od lizyna-prolina-walina, krótkiego fragmentu w kontekście melanokortyn. Cytowana publikacja bada go w mysich modelach nieswoistych zapaleń jelit. Nie jest to dowód kliniczny stosowania.","text_en":"KPV to skrót od lizyna-prolina-walina, krótkiego fragmentu w kontekście melanokortyn. Cytowana publikacja bada go w mysich modelach nieswoistych zapaleń jelit. Nie jest to dowód kliniczny stosowania.","synonyme":["Lys-Pro-Val","alfa-MSH(11-13)"],"synonyme_en":["Lys-Pro-Val","alfa-MSH(11-13)"],"link":"wirkstoffe/kpv.html"},{"slug":"kupferpeptid","begriff":"Peptydy miedziowe","begriff_en":"Peptydy miedziowe","kategorie":"klassen","kurz":"Peptydy miedziowe to kompleksy małego peptydu i jonu miedzi; najlepiej znany jest GHK-Cu.","kurz_en":"Peptydy miedziowe to kompleksy małego peptydu i jonu miedzi; najlepiej znany jest GHK-Cu.","quellen":[{"titel":"GHK jako peptyd wiążący miedź w krystalografii","titel_en":"GHK jako peptyd wiążący miedź w krystalografii","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC7709198/"}],"text":"Peptydy miedziowe to związki, w których mały peptyd koordynuje jon miedzi. Najlepiej znanym przykładem jest GHK, peptyd złożony z trzech aminokwasów, występujący w ludzkim osoczu krwi, ślinie i moczu, gdzie naturalnie jest związany z miedzią. W postaci kompleksu z miedzią GHK-Cu bada się głównie w badaniach nad skórą, z dodatkowymi danymi przedklinicznymi dotyczącymi tkanki łącznej i gojenia ran.","text_en":"Peptydy miedziowe to związki, w których mały peptyd koordynuje jon miedzi. Najlepiej znanym przykładem jest GHK, peptyd złożony z trzech aminokwasów, występujący w ludzkim osoczu krwi, ślinie i moczu, gdzie naturalnie jest związany z miedzią. W postaci kompleksu z miedzią GHK-Cu bada się głównie w badaniach nad skórą, z dodatkowymi danymi przedklinicznymi dotyczącymi tkanki łącznej i gojenia ran.","synonyme":["Kompleksy GHK-Cu"],"synonyme_en":["Kompleksy GHK-Cu"],"siehe":["aminosaeure","peptid"],"wirkstoffe":["ghk-cu"],"seiten":["peptid-1x1.html"]},{"slug":"lagerung","begriff":"Przechowywanie","begriff_en":"Przechowywanie","kategorie":"handhabung","kurz":"Przechowywanie opisuje sposób, w jaki peptyd jest trzymany przed użyciem, zwykle w chłodzie, w suchym i ciemnym miejscu, zależnie od jego stanu.","kurz_en":"Przechowywanie opisuje sposób, w jaki peptyd jest trzymany przed użyciem, zwykle w chłodzie, w suchym i ciemnym miejscu, zależnie od jego stanu.","quellen":[{"titel":"Hoofnagle et al. (2016): Analiza peptydów i postępowanie w laboratorium","titel_en":"Hoofnagle et al. (2016): Analiza peptydów i postępowanie w laboratorium","url":"https://pubmed.ncbi.nlm.nih.gov/26719571/"}],"text":"Trwałość zależy między innymi od sekwencji, formulacji i warunków. Decydujące są specyfikacja materiału i uzasadnione dane o stabilności.","text_en":"Trwałość zależy między innymi od sekwencji, formulacji i warunków. Decydujące są specyfikacja materiału i uzasadnione dane o stabilności.","siehe":["lyophilisat","lichtschutz","rekonstitution"]},{"slug":"lichtschutz","begriff":"Ochrona przed światłem","begriff_en":"Ochrona przed światłem","kategorie":"handhabung","kurz":"Ochrona przed światłem obejmuje środki chroniące próbkę przed ekspozycją na światło, takie jak fiolki bursztynowe lub przechowywanie w ciemności.","kurz_en":"Ochrona przed światłem obejmuje środki chroniące próbkę przed ekspozycją na światło, takie jak fiolki bursztynowe lub przechowywanie w ciemności.","quellen":[{"titel":"ICH Q1B: Testy fotostabilności","titel_en":"ICH Q1B: Testy fotostabilności","url":"https://www.ema.europa.eu/en/scientific-guidelines/ich-q1b-photostability-testing-new-active-substances-medicinal-products"}],"text":"Badania fotostabilności sprawdzają, czy światło zmienia substancję lub formulację. Odpowiednie opakowanie może ograniczyć ekspozycję. Wymagane warunki zależą od produktu; sama ochrona przed światłem nie ustala określonego okresu trwałości.","text_en":"Badania fotostabilności sprawdzają, czy światło zmienia substancję lub formulację. Odpowiednie opakowanie może ograniczyć ekspozycję. Wymagane warunki zależą od produktu; sama ochrona przed światłem nie ustala określonego okresu trwałości.","siehe":["lagerung","lyophilisat"]},{"slug":"ll-37","begriff":"LL-37","begriff_en":"LL-37","kategorie":"wirkstoff","kurz":"Endogenny peptyd przeciwdrobnoustrojowy badany także w klinicznych badaniach dotyczących ran.","kurz_en":"Endogenny peptyd przeciwdrobnoustrojowy badany także w klinicznych badaniach dotyczących ran.","quellen":[{"titel":"PubMed: Publikacja badawcza, PMID 25041740","titel_en":"PubMed: Publikacja badawcza, PMID 25041740","url":"https://pubmed.ncbi.nlm.nih.gov/25041740/"}],"text":"Powiązane badanie randomizowane bada LL-37 w trudno gojących się żylnych owrzodzeniach goleni. Jego wyniki dotyczą konkretnego preparatu i schematu badania, a nie każdego produktu oznaczonego jako LL-37.","text_en":"Powiązane badanie randomizowane bada LL-37 w trudno gojących się żylnych owrzodzeniach goleni. Jego wyniki dotyczą konkretnego preparatu i schematu badania, a nie każdego produktu oznaczonego jako LL-37.","synonyme":["Katelicydyna","hCAP18(134-170)","Ludzka katelicydyna"],"synonyme_en":["Katelicydyna","hCAP18(134-170)","Ludzka katelicydyna"],"link":"wirkstoffe/ll-37.html"},{"slug":"lyophilisat","begriff":"Lyofilizat","begriff_en":"Lyofilizat","kategorie":"handhabung","kurz":"Materiał uzyskany przez liofilizację, na przykład proszek w fiolce laboratoryjnej.","kurz_en":"Materiał uzyskany przez liofilizację, na przykład proszek w fiolce laboratoryjnej.","quellen":[{"titel":"FDA: Liofilizacja","titel_en":"FDA: Liofilizacja","url":"https://www.fda.gov/inspections-compliance-enforcement-and-criminal-investigations/inspection-guides/lyophilization-parenteral-793"}],"text":"Liofilizacja usuwa wodę z zamrożonej próbki pod próżnią. Pozostaje suchy proszek lub porowata pastylka. Trwałość i okres przydatności zależą od substancji, formulacji i opakowania; sama postać fizyczna ich nie gwarantuje.","text_en":"Liofilizacja usuwa wodę z zamrożonej próbki pod próżnią. Pozostaje suchy proszek lub porowata pastylka. Trwałość i okres przydatności zależą od substancji, formulacji i opakowania; sama postać fizyczna ich nie gwarantuje.","siehe":["rekonstitution","lagerung","lichtschutz","charge"]},{"slug":"massenspektrometrie","begriff":"Spektrometria mas","begriff_en":"Spektrometria mas","kategorie":"labor","kurz":"Spektrometria mas określa masę cząsteczkową próbki i w ten sposób potwierdza, która cząsteczka jest faktycznie obecna.","kurz_en":"Spektrometria mas określa masę cząsteczkową próbki i w ten sposób potwierdza, która cząsteczka jest faktycznie obecna.","quellen":[{"titel":"FDA: Analiza złożonych mieszanin i peptydów","titel_en":"FDA: Analiza złożonych mieszanin i peptydów","url":"https://www.fda.gov/industry/generic-drug-user-fee-amendments/fys-2013-2017-regulatory-science-report-complex-mixtures-and-peptides"}],"text":"W połączeniu z chromatografią cieczową (LC-MS) potwierdza tożsamość peptydu niezależnie od jego wartości czystości. Wysoka wartość czystości bez takiego sprawdzenia nic nie mówi o tym, czy w ogóle obecna jest właściwa cząsteczka.","text_en":"W połączeniu z chromatografią cieczową (LC-MS) potwierdza tożsamość peptydu niezależnie od jego wartości czystości. Wysoka wartość czystości bez takiego sprawdzenia nic nie mówi o tym, czy w ogóle obecna jest właściwa cząsteczka.","synonyme":["MS"],"synonyme_en":["MS"],"siehe":["identitaet","hplc","coa"],"seiten":["peptid-1x1.html"]},{"slug":"melanocortin","begriff":"Melanokortyny","begriff_en":"Melanokortyny","kategorie":"klassen","kurz":"Melanokortyny to hormony peptydowe pochodzące z POMC, które wiążą pięć typów receptorów regulujących skórę, apetyt i reakcję seksualną.","kurz_en":"Melanokortyny to hormony peptydowe pochodzące z POMC, które wiążą pięć typów receptorów regulujących skórę, apetyt i reakcję seksualną.","quellen":[{"titel":"NCBI Endotext: Receptory melanokortynowe","titel_en":"NCBI Endotext: Receptory melanokortynowe","url":"https://www.ncbi.nlm.nih.gov/books/NBK279118/"}],"text":"Melanokortyny to rodzina hormonów peptydowych pochodzących z białka prekursorowego proopiomelanokortyny (POMC), w tym alfa-MSH i ACTH. Wiążą pięć odrębnych receptorów melanokortynowych (MC1R do MC5R), które regulują między innymi pigmentację skóry, apetyt, bilans energetyczny, procesy zapalne i reakcję seksualną. Syntetyczni agoniści receptorów melanokortynowych działają na pojedyncze receptory w tym układzie.","text_en":"Melanokortyny to rodzina hormonów peptydowych pochodzących z białka prekursorowego proopiomelanokortyny (POMC), w tym alfa-MSH i ACTH. Wiążą pięć odrębnych receptorów melanokortynowych (MC1R do MC5R), które regulują między innymi pigmentację skóry, apetyt, bilans energetyczny, procesy zapalne i reakcję seksualną. Syntetyczni agoniści receptorów melanokortynowych działają na pojedyncze receptory w tym układzie.","synonyme":["Układ melanokortynowy"],"synonyme_en":["Układ melanokortynowy"],"siehe":["rezeptor","agonist","peptidhormon"],"wirkstoffe":["melanotan-2","pt-141"],"seiten":["peptid-1x1.html"]},{"slug":"melanotan-2","begriff":"Melanotan II","begriff_en":"Melanotan II","kategorie":"wirkstoff","kurz":"Syntetyczny analog melanokortyn badany we wczesnych badaniach klinicznych.","kurz_en":"Syntetyczny analog melanokortyn badany we wczesnych badaniach klinicznych.","quellen":[{"titel":"PubMed: Publikacja badawcza, PMID 8637402","titel_en":"PubMed: Publikacja badawcza, PMID 8637402","url":"https://pubmed.ncbi.nlm.nih.gov/8637402/"}],"text":"Cytowana wczesna publikacja fazy I bada melanotan II w małym badaniu pilotażowym. Nie ustala wiarygodnej oceny stosunku korzyści do ryzyka dla ogólnego stosowania.","text_en":"Cytowana wczesna publikacja fazy I bada melanotan II w małym badaniu pilotażowym. Nie ustala wiarygodnej oceny stosunku korzyści do ryzyka dla ogólnego stosowania.","synonyme":["MT-2","MT2"],"synonyme_en":["MT-2","MT2"],"link":"wirkstoffe/melanotan-2.html"},{"slug":"metaanalyse","begriff":"Metaanaliza","begriff_en":"Metaanaliza","kategorie":"studien","kurz":"Statystyczne połączenie wielu badań dotyczących wspólnego pytania.","kurz_en":"Statystyczne połączenie wielu badań dotyczących wspólnego pytania.","quellen":[{"titel":"NCI: metaanaliza","titel_en":"NCI: metaanaliza","url":"https://www.cancer.gov/publications/dictionaries/cancer-terms/def/meta-analysis"}],"text":"Metaanaliza statystycznie łączy porównywalne wyniki wielu badań. Może dawać dokładniejsze oszacowania. Jej siła zależy od jakości, porównywalności i kompletności włączonych dowodów.","text_en":"Metaanaliza statystycznie łączy porównywalne wyniki wielu badań. Może dawać dokładniejsze oszacowania. Jej siła zależy od jakości, porównywalności i kompletności włączonych dowodów.","siehe":["klinische-studie","peer-review"],"seiten":["studien.html"]},{"slug":"milligramm-mikrogramm","begriff":"Miligram / Mikrogram","begriff_en":"Miligram / Mikrogram","kategorie":"handhabung","kurz":"Jeden miligram to 1000 mikrogramów, standardowa jednostka masy dla niewielkich ilości peptydów na etykietach i w CoA.","kurz_en":"Jeden miligram to 1000 mikrogramów, standardowa jednostka masy dla niewielkich ilości peptydów na etykietach i w CoA.","quellen":[{"titel":"BIPM: Przedrostki SI","titel_en":"BIPM: Przedrostki SI","url":"https://www.bipm.org/en/committees/cg/cgpm/11-1960/resolution-12"}],"text":"Miligramy (mg) i mikrogramy (µg) są podjednostkami grama i różnią się współczynnikiem 1000. Etykiety fiolek i CoA zwykle podają ilość peptydu w miligramach, natomiast wartości pojedynczych składników bywają podawane w mikrogramach. Kalkulator na tej stronie przelicza gramy, miligramy i mikrogramy w sposób czysto matematyczny.","text_en":"Miligramy (mg) i mikrogramy (µg) są podjednostkami grama i różnią się współczynnikiem 1000. Etykiety fiolek i CoA zwykle podają ilość peptydu w miligramach, natomiast wartości pojedynczych składników bywają podawane w mikrogramach. Kalkulator na tej stronie przelicza gramy, miligramy i mikrogramy w sposób czysto matematyczny.","siehe":["konzentration","internationale-einheit"],"seiten":["rechner.html"]},{"slug":"mitochondriales-peptid","begriff":"Peptydy mitochondrialne","begriff_en":"Peptydy mitochondrialne","kategorie":"klassen","kurz":"Peptydy mitochondrialne oddziałują na komórkową produkcję energii lub pochodzą z mitochondrialnego DNA.","kurz_en":"Peptydy mitochondrialne oddziałują na komórkową produkcję energii lub pochodzą z mitochondrialnego DNA.","quellen":[{"titel":"Lee et al. (2015): MOTS-c, badania przedkliniczne","titel_en":"Lee et al. (2015): MOTS-c, badania przedkliniczne","url":"https://doi.org/10.1016/j.cmet.2015.02.009"},{"titel":"Cho et al. (2007): Cele mitochondrialne w modelu szczurzym","titel_en":"Cho et al. (2007): Cele mitochondrialne w modelu szczurzym","url":"https://pubmed.ncbi.nlm.nih.gov/17429296/"}],"text":"Peptydy mitochondrialne nie stanowią jednej klasy substancji w klasycznym sensie. Termin grupuje peptydy, które wiążą się z wewnętrzną błoną mitochondrialną albo są kodowane przez mitochondrialne, a nie jądrowe DNA. Do drugiej grupy należy krótki peptyd pochodzący z mitochondrialnego genu 12S rRNA, badany w badaniach nad metabolizmem. Inny przykład wiąże kardiolipinę w wewnętrznej błonie i jest wykorzystywany w badaniach nad starzeniem się komórek i metabolizmem energetycznym.","text_en":"Peptydy mitochondrialne nie stanowią jednej klasy substancji w klasycznym sensie. Termin grupuje peptydy, które wiążą się z wewnętrzną błoną mitochondrialną albo są kodowane przez mitochondrialne, a nie jądrowe DNA. Do drugiej grupy należy krótki peptyd pochodzący z mitochondrialnego genu 12S rRNA, badany w badaniach nad metabolizmem. Inny przykład wiąże kardiolipinę w wewnętrznej błonie i jest wykorzystywany w badaniach nad starzeniem się komórek i metabolizmem energetycznym.","synonyme":["Peptydy mitochondrialne"],"synonyme_en":["Peptydy mitochondrialne"],"siehe":["praeklinisch","in-vitro"],"wirkstoffe":["mots-c","ss-31"],"seiten":["studien.html"]},{"slug":"mots-c","begriff":"MOTS-c","begriff_en":"MOTS-c","kategorie":"wirkstoff","kurz":"Peptyd pochodzący z mitochondrialnego DNA, badany w przedklinicznych modelach metabolicznych.","kurz_en":"Peptyd pochodzący z mitochondrialnego DNA, badany w przedklinicznych modelach metabolicznych.","quellen":[{"titel":"Lee et al. (2015): MOTS-c, badania przedkliniczne","titel_en":"Lee et al. (2015): MOTS-c, badania przedkliniczne","url":"https://doi.org/10.1016/j.cmet.2015.02.009"}],"text":"Publikacja opisująca odkrycie przedstawia krótką sekwencję zakodowaną w mitochondrialnym DNA i bada ją w modelach komórkowych i zwierzęcych. Jej rola w badaniach nad mitochondriami nie dowodzi korzyści z produktu dostępnego na rynku.","text_en":"Publikacja opisująca odkrycie przedstawia krótką sekwencję zakodowaną w mitochondrialnym DNA i bada ją w modelach komórkowych i zwierzęcych. Jej rola w badaniach nad mitochondriami nie dowodzi korzyści z produktu dostępnego na rynku.","synonyme":["Peptyd pochodzenia mitochondrialnego MOTS-c","Mitochondrialna otwarta ramka odczytu genu 12S rRNA typu c"],"synonyme_en":["Peptyd pochodzenia mitochondrialnego MOTS-c","Mitochondrialna otwarta ramka odczytu genu 12S rRNA typu c"],"link":"wirkstoffe/mots-c.html"},{"slug":"neuropeptid","begriff":"Neuropeptyd","begriff_en":"Neuropeptyd","kategorie":"grundlagen","kurz":"Peptyd działający jako cząsteczka sygnałowa między komórkami układu nerwowego.","kurz_en":"Peptyd działający jako cząsteczka sygnałowa między komórkami układu nerwowego.","quellen":[{"titel":"Purves et al.: Neuroprzekaźniki peptydowe","titel_en":"Purves et al.: Neuroprzekaźniki peptydowe","url":"https://www.ncbi.nlm.nih.gov/books/NBK10873/"}],"text":"Neuropeptydy to peptydy uwalniane przez komórki nerwowe, które działają jako cząsteczki sygnałowe w układzie nerwowym. Różnią się od klasycznych neuroprzekaźników większą cząsteczką i wiążą się również ze swoistymi receptorami na komórkach docelowych. W badaniach neuropeptydy służą między innymi do mapowania szlaków sygnałowych w ośrodkowym układzie nerwowym.","text_en":"Neuropeptydy to peptydy uwalniane przez komórki nerwowe, które działają jako cząsteczki sygnałowe w układzie nerwowym. Różnią się od klasycznych neuroprzekaźników większą cząsteczką i wiążą się również ze swoistymi receptorami na komórkach docelowych. W badaniach neuropeptydy służą między innymi do mapowania szlaków sygnałowych w ośrodkowym układzie nerwowym.","siehe":["peptid","peptidhormon","rezeptor"]},{"slug":"nootropikum","begriff":"Nootropiki","begriff_en":"Nootropiki","kategorie":"klassen","kurz":"Nootropiki to szeroka klasa substancji badanych w związku z pamięcią, uczeniem się lub przetwarzaniem stresu.","kurz_en":"Nootropiki to szeroka klasa substancji badanych w związku z pamięcią, uczeniem się lub przetwarzaniem stresu.","quellen":[{"titel":"Giurgea (1972): Pochodzenie koncepcji nootropowej","titel_en":"Giurgea (1972): Pochodzenie koncepcji nootropowej","url":"https://pubmed.ncbi.nlm.nih.gov/4541214/"}],"text":"Termin wprowadzony przez Giurgeę w 1972 roku opisuje substancje badane w związku z funkcjami poznawczymi. Sama etykieta nie potwierdza ani korzyści, ani bezpieczeństwa. Różne substancje i schematy badań wymagają osobnej oceny.","text_en":"Termin wprowadzony przez Giurgeę w 1972 roku opisuje substancje badane w związku z funkcjami poznawczymi. Sama etykieta nie potwierdza ani korzyści, ani bezpieczeństwa. Różne substancje i schematy badań wymagają osobnej oceny.","synonyme":["Smart Drugs"],"synonyme_en":["Smart Drugs"],"siehe":["neuropeptid","rezeptor"],"wirkstoffe":["semax","selank","dihexa"],"seiten":["peptid-1x1.html"]},{"slug":"oligopeptid","begriff":"Oligopeptyd","begriff_en":"Oligopeptyd","kategorie":"grundlagen","kurz":"Krótki łańcuch aminokwasów, klasyfikowany ze względu na długość jako di-, tri- lub oligopeptyd.","kurz_en":"Krótki łańcuch aminokwasów, klasyfikowany ze względu na długość jako di-, tri- lub oligopeptyd.","quellen":[{"titel":"Alberts et al.: Struktura białek","titel_en":"Alberts et al.: Struktura białek","url":"https://www.ncbi.nlm.nih.gov/books/NBK26830/"}],"langform":"Di-, tri- i oligopeptyd","langform_en":"Di-, tri- i oligopeptyd","text":"Oligopeptydy zawierają niewielką liczbę aminokwasów. Dwa tworzą dipeptyd, trzy tripeptyd. Granica z dłuższymi polipeptydami jest konwencją nazewniczą, a nie odrębną zmianą typu cząsteczki.","text_en":"Oligopeptydy zawierają niewielką liczbę aminokwasów. Dwa tworzą dipeptyd, trzy tripeptyd. Granica z dłuższymi polipeptydami jest konwencją nazewniczą, a nie odrębną zmianą typu cząsteczki.","synonyme":["Dipeptyd","Tripeptyd"],"synonyme_en":["Dipeptyd","Tripeptyd"],"siehe":["peptid","aminosaeure","protein"],"seiten":["peptid-1x1.html"]},{"slug":"oxytocin","begriff":"Oksytocyna","begriff_en":"Oksytocyna","kategorie":"wirkstoff","kurz":"Endogenny hormon peptydowy badany także w badaniach zachowań społecznych.","kurz_en":"Endogenny hormon peptydowy badany także w badaniach zachowań społecznych.","quellen":[{"titel":"PubMed: Publikacja badawcza, PMID 15931222","titel_en":"PubMed: Publikacja badawcza, PMID 15931222","url":"https://pubmed.ncbi.nlm.nih.gov/15931222/"}],"text":"Powiązane badanie behawioralne analizuje decyzje w eksperymentalnej grze zaufania. Takie wyniki nie dowodzą ani ogólnej poprawy relacji społecznych, ani bezpieczeństwa produktów swobodnie sprzedawanych na rynku.","text_en":"Powiązane badanie behawioralne analizuje decyzje w eksperymentalnej grze zaufania. Takie wyniki nie dowodzą ani ogólnej poprawy relacji społecznych, ani bezpieczeństwa produktów swobodnie sprzedawanych na rynku.","synonyme":["OXT","Pitocin"],"synonyme_en":["OXT","Pitocin"],"link":"wirkstoffe/oxytocin.html"},{"slug":"partnercode","begriff":"Kod partnera","begriff_en":"Kod partnera","kategorie":"vergleich","kurz":"Kod powiązany z programem afiliacyjnym, podlegający warunkom dostawcy.","kurz_en":"Kod powiązany z programem afiliacyjnym, podlegający warunkom dostawcy.","quellen":[{"titel":"Peptide Compass: Nasza informacja o afiliacji","titel_en":"Peptide Compass: Nasza informacja o afiliacji","url":"https://peptidkompass.com/pl/affiliate-hinweis.html"}],"text":"Kod partnera jest powiązany z programem afiliacyjnym. To, czy daje rabat, czy prowizję, zależy od obowiązujących warunków. Aktualnie udokumentowane partnerstwa i kody podajemy w naszej informacji o afiliacji; nie zmieniają one wyniku dokumentacji.","text_en":"Kod partnera jest powiązany z programem afiliacyjnym. To, czy daje rabat, czy prowizję, zależy od obowiązujących warunków. Aktualnie udokumentowane partnerstwa i kody podajemy w naszej informacji o afiliacji; nie zmieniają one wyniku dokumentacji.","siehe":["affiliate-link"],"seiten":["affiliate-hinweis.html","deals.html"]},{"slug":"peer-review","begriff":"Recenzja naukowa (peer review)","begriff_en":"Recenzja naukowa (peer review)","kategorie":"studien","kurz":"Ocena rękopisu badania przez niezależnych specjalistów przed publikacją.","kurz_en":"Ocena rękopisu badania przez niezależnych specjalistów przed publikacją.","quellen":[{"titel":"NIH: Wytyczne dotyczące recenzji naukowej","titel_en":"NIH: Wytyczne dotyczące recenzji naukowej","url":"https://oir.nih.gov/system/files/media/file/2026-01/guidelines-conduct_research.pdf"}],"text":"W recenzji naukowej niezależni eksperci sprawdzają metodologię, analizę danych i wnioski w rękopisie przed publikacją. Mogą żądać poprawek lub odrzucić pracę. Publikacja po recenzji naukowej uchodzi za bardziej wiarygodną niż tekst bez recenzji, choć nie gwarantuje braku błędów.","text_en":"W recenzji naukowej niezależni eksperci sprawdzają metodologię, analizę danych i wnioski w rękopisie przed publikacją. Mogą żądać poprawek lub odrzucić pracę. Publikacja po recenzji naukowej uchodzi za bardziej wiarygodną niż tekst bez recenzji, choć nie gwarantuje braku błędów.","siehe":["preprint","pubmed"],"seiten":["studien.html"]},{"slug":"pentadeca-arginate","begriff":"Pentadeca Arginate (PDA)","begriff_en":"Pentadeca Arginate","kategorie":"wirkstoff","kurz":"Nazwa handlowa formy sprzedawanej jako sól argininowa BPC-157.","kurz_en":"Nazwa handlowa formy sprzedawanej jako sól argininowa BPC-157.","quellen":[{"titel":"PubMed: Publikacja badawcza, PMID 27847966","titel_en":"PubMed: Publikacja badawcza, PMID 27847966","url":"https://pubmed.ncbi.nlm.nih.gov/27847966/"}],"text":"Cytowane badanie źródłowe dotyczy BPC-157. Nie wykazuje szczególnych właściwości formy solnej sprzedawanej jako pentadeca arginate. Nie ustalono tu wiarygodnego, dedykowanego źródła wykazującego lepszą rozpuszczalność lub stabilność tej formy dostępnej na rynku.","text_en":"Cytowane badanie źródłowe dotyczy BPC-157. Nie wykazuje szczególnych właściwości formy solnej sprzedawanej jako pentadeca arginate. Nie ustalono tu wiarygodnego, dedykowanego źródła wykazującego lepszą rozpuszczalność lub stabilność tej formy dostępnej na rynku.","synonyme":["PDA","Sól argininowa BPC-157"],"synonyme_en":["PDA","Sól argininowa BPC-157"],"link":"wirkstoffe/pentadeca-arginate.html"},{"slug":"peptid","begriff":"Peptyd","begriff_en":"Peptydy","kategorie":"grundlagen","kurz":"Krótki łańcuch aminokwasów połączonych wiązaniami peptydowymi.","kurz_en":"Krótki łańcuch aminokwasów połączonych wiązaniami peptydowymi.","quellen":[{"titel":"NCI: peptyd","titel_en":"NCI: peptyd","url":"https://www.cancer.gov/publications/dictionaries/cancer-terms/def/peptide"}],"text":"Dwa połączone aminokwasy tworzą dipeptyd, trzy tworzą tripeptyd. Dłuższe łańcuchy nazywa się też polipeptydami. Sztywna granica 50 aminokwasów nie rozróżnia peptydów i białek we wszystkich dziedzinach.","text_en":"Dwa połączone aminokwasy tworzą dipeptyd, trzy tworzą tripeptyd. Dłuższe łańcuchy nazywa się też polipeptydami. Sztywna granica 50 aminokwasów nie rozróżnia peptydów i białek we wszystkich dziedzinach.","synonyme":["Peptydy"],"synonyme_en":["Peptydy"],"siehe":["aminosaeure","peptidbindung","oligopeptid","protein"],"seiten":["peptid-1x1.html"]},{"slug":"peptidbindung","begriff":"Wiązanie peptydowe","begriff_en":"Wiązanie peptydowe","kategorie":"grundlagen","kurz":"Wiązanie chemiczne łączące dwa aminokwasy w łańcuch.","kurz_en":"Wiązanie chemiczne łączące dwa aminokwasy w łańcuch.","quellen":[{"titel":"Alberts et al.: Struktura białek","titel_en":"Alberts et al.: Struktura białek","url":"https://www.ncbi.nlm.nih.gov/books/NBK26830/"}],"text":"Wiązanie peptydowe powstaje, gdy grupa karboksylowa jednego aminokwasu reaguje z grupą aminową następnego, a przy tym uwalnia się cząsteczka wody. To połączenie powtarza się wzdłuż całego łańcucha i tworzy szkielet peptydów i białek. Kolejność tak połączonych aminokwasów ustala sekwencję.","text_en":"Wiązanie peptydowe powstaje, gdy grupa karboksylowa jednego aminokwasu reaguje z grupą aminową następnego, a przy tym uwalnia się cząsteczka wody. To połączenie powtarza się wzdłuż całego łańcucha i tworzy szkielet peptydów i białek. Kolejność tak połączonych aminokwasów ustala sekwencję.","siehe":["aminosaeure","peptid","sequenz"]},{"slug":"peptidgehalt","begriff":"Zawartość netto peptydu","begriff_en":"Zawartość netto peptydu","kategorie":"labor","kurz":"Zawartość netto peptydu wskazuje, jaka część masy proszku to sam peptyd.","kurz_en":"Zawartość netto peptydu wskazuje, jaka część masy proszku to sam peptyd.","quellen":[{"titel":"Hoofnagle et al. (2016): Analiza peptydów i postępowanie w laboratorium","titel_en":"Hoofnagle et al. (2016): Analiza peptydów i postępowanie w laboratorium","url":"https://pubmed.ncbi.nlm.nih.gov/26719571/"}],"text":"Zawartość peptydu to faktyczny udział peptydu w próbce. Woda i inne składniki mogą sprawiać, że masa proszku różni się od masy peptydu.","text_en":"Zawartość peptydu to faktyczny udział peptydu w próbce. Woda i inne składniki mogą sprawiać, że masa proszku różni się od masy peptydu.","siehe":["reinheit","gegenion","coa"],"seiten":["methodik.html"]},{"slug":"peptidhormon","begriff":"Hormon peptydowy","begriff_en":"Hormon peptydowy","kategorie":"grundlagen","kurz":"Hormon wytwarzany przez organizm, który chemicznie jest łańcuchem aminokwasów.","kurz_en":"Hormon wytwarzany przez organizm, który chemicznie jest łańcuchem aminokwasów.","quellen":[{"titel":"Purves et al.: Neuroprzekaźniki peptydowe","titel_en":"Purves et al.: Neuroprzekaźniki peptydowe","url":"https://www.ncbi.nlm.nih.gov/books/NBK10873/"}],"text":"Hormon peptydowy to cząsteczka sygnałowa zbudowana z łańcucha aminokwasów, w przeciwieństwie do hormonów steroidowych, które powstają z cholesterolu. Hormony peptydowe powstają w gruczołach lub wyspecjalizowanych komórkach i wiążą się z receptorami na komórkach docelowych. Insulina jest dobrze znanym przykładem endogennego hormonu peptydowego.","text_en":"Hormon peptydowy to cząsteczka sygnałowa zbudowana z łańcucha aminokwasów, w przeciwieństwie do hormonów steroidowych, które powstają z cholesterolu. Hormony peptydowe powstają w gruczołach lub wyspecjalizowanych komórkach i wiążą się z receptorami na komórkach docelowych. Insulina jest dobrze znanym przykładem endogennego hormonu peptydowego.","siehe":["peptid","rezeptor","neuropeptid"]},{"slug":"placebo","begriff":"Placebo","begriff_en":"Placebo","kategorie":"studien","kurz":"Preparat obojętny bez substancji czynnej, używany w badaniu do porównania z rzeczywistą substancją. Oddziela rzeczywiste działanie od oczekiwanego.","kurz_en":"Preparat obojętny bez substancji czynnej, używany w badaniu do porównania z rzeczywistą substancją. Oddziela rzeczywiste działanie od oczekiwanego.","quellen":[{"titel":"NCI: placebo","titel_en":"NCI: placebo","url":"https://www.cancer.gov/publications/dictionaries/cancer-terms/def/placebo"}],"text":"Placebo wygląda jak badany preparat, ale nie zawiera substancji czynnej. W schemacie badania pełni rolę grupy porównawczej i pokazuje, jak duża część reakcji wynika z oczekiwań uczestnika, a nie z samej substancji. Kontrola placebo jest podstawową cechą informatywnych badań klinicznych i często łączy się ją z zaślepieniem.","text_en":"Placebo wygląda jak badany preparat, ale nie zawiera substancji czynnej. W schemacie badania pełni rolę grupy porównawczej i pokazuje, jak duża część reakcji wynika z oczekiwań uczestnika, a nie z samej substancji. Kontrola placebo jest podstawową cechą informatywnych badań klinicznych i często łączy się ją z zaślepieniem.","synonyme":["Preparat nieczynny"],"synonyme_en":["Preparat nieczynny"],"siehe":["rct","Podwójnie ślepa próba"],"seiten":["studien.html"]},{"slug":"praeklinisch","begriff":"Etap przedkliniczny","begriff_en":"Etap przedkliniczny","kategorie":"studien","kurz":"Etap badań przed jakimkolwiek zastosowaniem u ludzi: hodowle komórkowe i model zwierzęcy. Badania kliniczne następują dopiero po tym etapie.","kurz_en":"Etap badań przed jakimkolwiek zastosowaniem u ludzi: hodowle komórkowe i model zwierzęcy. Badania kliniczne następują dopiero po tym etapie.","quellen":[{"titel":"NCI: badanie przedkliniczne","titel_en":"NCI: badanie przedkliniczne","url":"https://www.cancer.gov/publications/dictionaries/cancer-terms/def/preclinical-study"}],"text":"Badania przedkliniczne obejmują doświadczenia in vitro i in vivo, które sprawdzają wczesne działanie i bezpieczeństwo, zanim substancję w ogóle przebada się u ludzi. Dostarczają podstaw danych dla ewentualnego późniejszego badania klinicznego. Sam wynik przedkliniczny nie uzasadnia twierdzeń dotyczących ludzi.","text_en":"Badania przedkliniczne obejmują doświadczenia in vitro i in vivo, które sprawdzają wczesne działanie i bezpieczeństwo, zanim substancję w ogóle przebada się u ludzi. Dostarczają podstaw danych dla ewentualnego późniejszego badania klinicznego. Sam wynik przedkliniczny nie uzasadnia twierdzeń dotyczących ludzi.","synonyme":["Badania przedkliniczne"],"synonyme_en":["Badania przedkliniczne"],"siehe":["in-vitro","in-vivo","tiermodell","klinische-studie"],"seiten":["studien.html"]},{"slug":"preis-pro-mg","begriff":"Cena za miligram","begriff_en":"Cena za miligram","kategorie":"vergleich","kurz":"Cena za miligram pozwala na bezpośrednie porównanie ofert o różnych rozmiarach opakowań.","kurz_en":"Cena za miligram pozwala na bezpośrednie porównanie ofert o różnych rozmiarach opakowań.","quellen":[{"titel":"Peptide Compass: Nasza metodologia porównawcza","titel_en":"Peptide Compass: Nasza metodologia porównawcza","url":"https://peptidkompass.com/pl/methodik.html"}],"text":"Wartość to cena katalogowa podzielona przez zawartość produktu w miligramach, porównywana dla tej samej substancji czynnej i waluty. Koszty wysyłki, dostępność i warunki rabatów są uwzględniane tylko wtedy, gdy są wyraźnie udokumentowane. Niższa wartość nic nie mówi o czystości ani dokumentacji.","text_en":"Wartość to cena katalogowa podzielona przez zawartość produktu w miligramach, porównywana dla tej samej substancji czynnej i waluty. Koszty wysyłki, dostępność i warunki rabatów są uwzględniane tylko wtedy, gdy są wyraźnie udokumentowane. Niższa wartość nic nie mówi o czystości ani dokumentacji.","siehe":["dokumentationsscore"],"seiten":["vergleich.html","rechner.html"]},{"slug":"preprint","begriff":"Preprint","begriff_en":"Preprint","kategorie":"studien","kurz":"Rękopis badania opublikowany przed recenzją naukową. Wyniki uchodzą za wstępne, jeszcze niezależnie niezweryfikowane.","kurz_en":"Rękopis badania opublikowany przed recenzją naukową. Wyniki uchodzą za wstępne, jeszcze niezależnie niezweryfikowane.","quellen":[{"titel":"NLM: Ograniczenia PubMed i preprintów","titel_en":"NLM: Ograniczenia PubMed i preprintów","url":"https://pubmed.ncbi.nlm.nih.gov/disclaimer/"}],"text":"Preprint jest publikowany na otwartej platformie, zanim czasopismo go zrecenzuje. Przyspiesza to wymianę wyników, ale oznacza, że metodologia i wnioski nie zostały jeszcze niezależnie sprawdzone. Treści z preprintu należy oceniać ostrożniej niż publikację po recenzji naukowej.","text_en":"Preprint jest publikowany na otwartej platformie, zanim czasopismo go zrecenzuje. Przyspiesza to wymianę wyników, ale oznacza, że metodologia i wnioski nie zostały jeszcze niezależnie sprawdzone. Treści z preprintu należy oceniać ostrożniej niż publikację po recenzji naukowej.","siehe":["peer-review","pubmed"],"seiten":["studien.html"]},{"slug":"protein","begriff":"Białko","begriff_en":"Białko","kategorie":"grundlagen","kurz":"Molekuła złożona z łańcuchów aminokwasowych o różnorodnych rolach biologicznych.","kurz_en":"Molekuła złożona z łańcuchów aminokwasowych o różnorodnych rolach biologicznych.","quellen":[{"titel":"NCI: białko","titel_en":"NCI: białko","url":"https://www.cancer.gov/publications/dictionaries/cancer-terms/def/protein"}],"text":"Białka składają się z jednego lub kilku łańcuchów aminokwasów. Ich sekwencja i struktura przestrzenna określają ich właściwości. Sama stała długość łańcucha nie wyznacza różnicy względem peptydów.","text_en":"Białka składają się z jednego lub kilku łańcuchów aminokwasów. Ich sekwencja i struktura przestrzenna określają ich właściwości. Sama stała długość łańcucha nie wyznacza różnicy względem peptydów.","synonyme":["Białko"],"synonyme_en":["Białko"],"siehe":["peptid","aminosaeure","oligopeptid"],"seiten":["peptid-1x1.html"]},{"slug":"proteolyse","begriff":"Proteoliza","begriff_en":"Proteoliza","kategorie":"grundlagen","kurz":"Enzymatyczny rozkład łańcucha aminokwasów na mniejsze fragmenty.","kurz_en":"Enzymatyczny rozkład łańcucha aminokwasów na mniejsze fragmenty.","quellen":[{"titel":"Alberts et al.: Synteza i degradacja białek","titel_en":"Alberts et al.: Synteza i degradacja białek","url":"https://www.ncbi.nlm.nih.gov/books/NBK26829/"}],"text":"Proteoliza to proces, w którym enzymy zwane proteazami przecinają wiązania peptydowe w łańcuchu aminokwasów, rozbijając go na mniejsze fragmenty. Rozkład ten zachodzi w organizmie nieustannie i wpływa na to, jak długo peptyd pozostaje nienaruszony, czyli na jego czas półtrwania. Badania często podają stabilność proteolityczną jako miarę trwałości peptydu.","text_en":"Proteoliza to proces, w którym enzymy zwane proteazami przecinają wiązania peptydowe w łańcuchu aminokwasów, rozbijając go na mniejsze fragmenty. Rozkład ten zachodzi w organizmie nieustannie i wpływa na to, jak długo peptyd pozostaje nienaruszony, czyli na jego czas półtrwania. Badania często podają stabilność proteolityczną jako miarę trwałości peptydu.","siehe":["halbwertszeit","peptidbindung","bioverfuegbarkeit"]},{"slug":"pt-141","begriff":"PT-141 (bremelanotide)","begriff_en":"PT-141 (bremelanotide)","kategorie":"wirkstoff","kurz":"Bremelanotide, syntetyczny agonista receptora melanokortynowego badany w badaniach klinicznych.","kurz_en":"Bremelanotide, syntetyczny agonista receptora melanokortynowego badany w badaniach klinicznych.","quellen":[{"titel":"PubMed: Publikacja badawcza, PMID 31599840","titel_en":"PubMed: Publikacja badawcza, PMID 31599840","url":"https://pubmed.ncbi.nlm.nih.gov/31599840/"}],"text":"PT-141 to inna nazwa bremelanotide. Powiązana publikacja opisuje dwa randomizowane badania fazy III w określonej populacji pacjentów. Produkt badawczy sprzedawany przez sklep nie jest równoważny preparatowi użytemu w badaniu.","text_en":"PT-141 to inna nazwa bremelanotide. Powiązana publikacja opisuje dwa randomizowane badania fazy III w określonej populacji pacjentów. Produkt badawczy sprzedawany przez sklep nie jest równoważny preparatowi użytemu w badaniu.","synonyme":["Bremelanotide","Vyleesi"],"synonyme_en":["Bremelanotide","Vyleesi"],"link":"wirkstoffe/pt-141.html"},{"slug":"pubmed","begriff":"PubMed","begriff_en":"PubMed","kategorie":"studien","kurz":"Bezpłatna baza danych prowadzona przez Narodową Bibliotekę Medyczną USA, obejmująca literaturę biomedyczną.","kurz_en":"Bezpłatna baza danych prowadzona przez Narodową Bibliotekę Medyczną USA, obejmująca literaturę biomedyczną.","quellen":[{"titel":"NLM: Ograniczenia PubMed i preprintów","titel_en":"NLM: Ograniczenia PubMed i preprintów","url":"https://pubmed.ncbi.nlm.nih.gov/disclaimer/"}],"text":"PubMed indeksuje miliony artykułów z medycyny i nauk o życiu i zwykle od razu pokazuje bezpłatne streszczenie. Pełny tekst często znajduje się za płatną barierą czasopisma. Wpis w PubMed potwierdza, że praca jest zindeksowana, ale nic nie mówi o jakości tego pojedynczego badania.","text_en":"PubMed indeksuje miliony artykułów z medycyny i nauk o życiu i zwykle od razu pokazuje bezpłatne streszczenie. Pełny tekst często znajduje się za płatną barierą czasopisma. Wpis w PubMed potwierdza, że praca jest zindeksowana, ale nic nie mówi o jakości tego pojedynczego badania.","siehe":["peer-review","preprint"],"seiten":["studien.html"]},{"slug":"rct","begriff":"RCT","begriff_en":"RCT","kategorie":"studien","kurz":"Schemat badania z losowym przydziałem do grupy leczonej i grupy kontrolnej. Uważany za złoty standard w wykazywaniu efektu.","kurz_en":"Schemat badania z losowym przydziałem do grupy leczonej i grupy kontrolnej. Uważany za złoty standard w wykazywaniu efektu.","quellen":[{"titel":"NCI: Randomizowane badania kliniczne","titel_en":"NCI: Randomizowane badania kliniczne","url":"https://www.cancer.gov/publications/patient-education/crs.pdf"}],"langform":"Randomizowane badanie kontrolowane","langform_en":"Randomizowane badanie kontrolowane","text":"W randomizowanym badaniu kontrolowanym uczestników losowo przydziela się do grupy leczonej lub kontrolnej, często także z zaślepieniem. Ogranicza to błędy wynikające z oczekiwań lub doboru. RCT uchodzą za metodologiczny złoty standard w badaniach klinicznych, zwłaszcza w połączeniu z kontrolą placebo.","text_en":"W randomizowanym badaniu kontrolowanym uczestników losowo przydziela się do grupy leczonej lub kontrolnej, często także z zaślepieniem. Ogranicza to błędy wynikające z oczekiwań lub doboru. RCT uchodzą za metodologiczny złoty standard w badaniach klinicznych, zwłaszcza w połączeniu z kontrolą placebo.","siehe":["placebo","Podwójnie ślepa próba","klinische-studie"],"seiten":["studien.html"]},{"slug":"reinheit","begriff":"Czystość","begriff_en":"Czystość","kategorie":"labor","kurz":"Czystość określa, jaka część pola piku chromatogramu próbki przypada na główną cząsteczkę, zwykle jako procent z HPLC.","kurz_en":"Czystość określa, jaka część pola piku chromatogramu próbki przypada na główną cząsteczkę, zwykle jako procent z HPLC.","quellen":[{"titel":"Hoofnagle et al. (2016): Analiza peptydów i postępowanie w laboratorium","titel_en":"Hoofnagle et al. (2016): Analiza peptydów i postępowanie w laboratorium","url":"https://pubmed.ncbi.nlm.nih.gov/26719571/"}],"text":"Czystość opisuje udział substancji docelowej w ramach podanej metody. Procent pola powierzchni z HPLC nie określa w pełni składu.","text_en":"Czystość opisuje udział substancji docelowej w ramach podanej metody. Procent pola powierzchni z HPLC nie określa w pełni składu.","siehe":["hplc","identitaet","peptidgehalt"],"seiten":["peptid-1x1.html"]},{"slug":"rekonstitution","begriff":"Rekonstytucja","begriff_en":"Rekonstytucja","kategorie":"handhabung","kurz":"Rekonstytucja to rozpuszczenie liofilizowanego peptydu w cieczy w celu przygotowania roztworu do użytku laboratoryjnego.","kurz_en":"Rekonstytucja to rozpuszczenie liofilizowanego peptydu w cieczy w celu przygotowania roztworu do użytku laboratoryjnego.","quellen":[{"titel":"FDA: Liofilizacja","titel_en":"FDA: Liofilizacja","url":"https://www.fda.gov/inspections-compliance-enforcement-and-criminal-investigations/inspection-guides/lyophilization-parenteral-793"}],"text":"Termin oznacza odtworzenie postaci płynnej z preparatu suchego. Odpowiednia ciecz zależy od substancji i procedury analitycznej. Termin nie oznacza ogólnej metody przygotowania ani podawania.","text_en":"Termin oznacza odtworzenie postaci płynnej z preparatu suchego. Odpowiednia ciecz zależy od substancji i procedury analitycznej. Termin nie oznacza ogólnej metody przygotowania ani podawania.","siehe":["lyophilisat","bakteriostatisches-wasser","steriles-wasser","konzentration"],"seiten":["rechner.html"]},{"slug":"retatrutid","begriff":"Retatrutyd","begriff_en":"Retatrutyd","kategorie":"wirkstoff","kurz":"Peptydowy agonista trzech receptorów badany w badaniach klinicznych.","kurz_en":"Peptydowy agonista trzech receptorów badany w badaniach klinicznych.","quellen":[{"titel":"PubMed: Publikacja badawcza, PMID 37366315","titel_en":"PubMed: Publikacja badawcza, PMID 37366315","url":"https://pubmed.ncbi.nlm.nih.gov/37366315/"}],"text":"Powiązane badanie fazy II bada agonistę receptorów GIP, GLP-1 i glukagonu. Wyniki tego badania nie dowodzą równoważności produktu sklepowego sprzedawanego pod tą samą nazwą.","text_en":"Powiązane badanie fazy II bada agonistę receptorów GIP, GLP-1 i glukagonu. Wyniki tego badania nie dowodzą równoważności produktu sklepowego sprzedawanego pod tą samą nazwą.","synonyme":["LY3437943"],"synonyme_en":["LY3437943"],"link":"wirkstoffe/retatrutid.html"},{"slug":"rezeptor","begriff":"Receptor","begriff_en":"Receptor","kategorie":"grundlagen","kurz":"Białko na komórce lub wewnątrz niej, z którym peptyd wiąże się swoiście.","kurz_en":"Białko na komórce lub wewnątrz niej, z którym peptyd wiąże się swoiście.","quellen":[{"titel":"NCI: receptor","titel_en":"NCI: receptor","url":"https://www.cancer.gov/publications/dictionaries/cancer-terms/def/receptor"}],"text":"Receptor to białko, które swoiście rozpoznaje i wiąże pasującą cząsteczkę, na przykład peptyd, jak zamek i klucz. To wiązanie uruchamia szlak sygnałowy wewnątrz komórki. W badaniach siłę, z jaką peptyd wiąże się z danym receptorem, nazywa się powinowactwem i często bada się ją w laboratorium na hodowlach komórkowych.","text_en":"Receptor to białko, które swoiście rozpoznaje i wiąże pasującą cząsteczkę, na przykład peptyd, jak zamek i klucz. To wiązanie uruchamia szlak sygnałowy wewnątrz komórki. W badaniach siłę, z jaką peptyd wiąże się z danym receptorem, nazywa się powinowactwem i często bada się ją w laboratorium na hodowlach komórkowych.","siehe":["agonist","peptidhormon","neuropeptid"]},{"slug":"rezeptpflicht","begriff":"Wymóg recepty","begriff_en":"Wymóg recepty","kategorie":"recht","kurz":"Wymóg recepty oznacza, że produkt leczniczy może być wydany wyłącznie na receptę lekarza.","kurz_en":"Wymóg recepty oznacza, że produkt leczniczy może być wydany wyłącznie na receptę lekarza.","quellen":[{"titel":"Niemiecka ustawa o lekach, § 48: Wymóg recepty","titel_en":"Niemiecka ustawa o lekach, § 48: Wymóg recepty","url":"https://www.gesetze-im-internet.de/amg_1976/__48.html"}],"text":"W Niemczech szczególne znaczenie mają § 48 ustawy o lekach oraz rozporządzenie o lekach wydawanych na receptę. Wymóg recepty, status produktu leczniczego i pozwolenie na dopuszczenie do obrotu to odrębne kwestie. Sprzedaż jako chemikaliów badawczych nie daje ogólnego zwolnienia.","text_en":"W Niemczech szczególne znaczenie mają § 48 ustawy o lekach oraz rozporządzenie o lekach wydawanych na receptę. Wymóg recepty, status produktu leczniczego i pozwolenie na dopuszczenie do obrotu to odrębne kwestie. Sprzedaż jako chemikaliów badawczych nie daje ogólnego zwolnienia.","siehe":["arzneimittel","zulassung"],"seiten":["peptid-1x1.html"]},{"slug":"ruo","begriff":"RUO","begriff_en":"RUO","kategorie":"recht","kurz":"Research Use Only opisuje cel badawczy. Sam ten skrót nie ustala statusu prawnego produktu.","kurz_en":"Research Use Only opisuje cel badawczy. Sam ten skrót nie ustala statusu prawnego produktu.","quellen":[{"titel":"Niemiecka ustawa o lekach, § 2: definicja leków","titel_en":"Niemiecka ustawa o lekach, § 2: definicja leków","url":"https://www.gesetze-im-internet.de/amg_1976/__2.html"},{"titel":"FDA (24 sierpnia 2026): Etykietowanie RUO i zamierzone zastosowanie, USA","titel_en":"FDA (24 sierpnia 2026): Etykietowanie RUO i zamierzone zastosowanie, USA","url":"https://www.fda.gov/inspections-compliance-enforcement-and-criminal-investigations/warning-letters/txp-innovations-llc-dba-tex-peptides-735067-08242026"}],"langform":"Research Use Only","langform_en":"Research Use Only","text":"Oznaczenie opisuje deklarowany przez dostawcę zamierzony cel. Nie jest ani pozwoleniem, ani dowodem czystości lub bezpieczeństwa. To, czy produkt prawnie kwalifikuje się jako lek, zależy od kryteriów ustawowych i faktycznego sposobu jego prezentacji, a nie wyłącznie od tego skrótu.","text_en":"Oznaczenie opisuje deklarowany przez dostawcę zamierzony cel. Nie jest ani pozwoleniem, ani dowodem czystości lub bezpieczeństwa. To, czy produkt prawnie kwalifikuje się jako lek, zależy od kryteriów ustawowych i faktycznego sposobu jego prezentacji, a nie wyłącznie od tego skrótu.","siehe":["arzneimittel","zulassung"],"seiten":["methodik.html"]},{"slug":"selank","begriff":"Selank","begriff_en":"Selank","kategorie":"wirkstoff","kurz":"Syntetyczny peptyd badany w badaniach nad zaburzeniami lękowymi.","kurz_en":"Syntetyczny peptyd badany w badaniach nad zaburzeniami lękowymi.","quellen":[{"titel":"PubMed: Publikacja badawcza, PMID 18454096","titel_en":"PubMed: Publikacja badawcza, PMID 18454096","url":"https://pubmed.ncbi.nlm.nih.gov/18454096/"}],"text":"Powiązana publikacja kliniczna porównuje selank z medazepamem w zaburzeniach lękowych i neurastenii. Pojedyncza publikacja nie zastępuje ani kompleksowej oceny dowodów, ani weryfikacji jakości produktów dostępnych na rynku.","text_en":"Powiązana publikacja kliniczna porównuje selank z medazepamem w zaburzeniach lękowych i neurastenii. Pojedyncza publikacja nie zastępuje ani kompleksowej oceny dowodów, ani weryfikacji jakości produktów dostępnych na rynku.","link":"wirkstoffe/selank.html"},{"slug":"semaglutid","begriff":"Semaglutyd","begriff_en":"Semaglutyd","kategorie":"wirkstoff","kurz":"Analog GLP-1 z badaniami klinicznymi i dopuszczonymi do obrotu produktami leczniczymi.","kurz_en":"Analog GLP-1 z badaniami klinicznymi i dopuszczonymi do obrotu produktami leczniczymi.","quellen":[{"titel":"PubMed: Publikacja badawcza, PMID 33567185","titel_en":"PubMed: Publikacja badawcza, PMID 33567185","url":"https://pubmed.ncbi.nlm.nih.gov/33567185/"},{"titel":"EMA: Pozwolenie dla konkretnego produktu Ozempic","titel_en":"EMA: Pozwolenie dla konkretnego produktu Ozempic","url":"https://www.ema.europa.eu/en/medicines/human/EPAR/ozempic"}],"text":"Powiązana publikacja kliniczna bada semaglutyd u dorosłych z nadwagą lub otyłością. Ocena EMA dotyczy konkretnego produktu leczniczego Ozempic. Ani badanie, ani pozwolenie nie weryfikują podobnie nazwanego produktu ze sklepu z odczynnikami badawczymi.","text_en":"Powiązana publikacja kliniczna bada semaglutyd u dorosłych z nadwagą lub otyłością. Ocena EMA dotyczy konkretnego produktu leczniczego Ozempic. Ani badanie, ani pozwolenie nie weryfikują podobnie nazwanego produktu ze sklepu z odczynnikami badawczymi.","link":"wirkstoffe/semaglutid.html"},{"slug":"semax","begriff":"Semax","begriff_en":"Semax","kategorie":"wirkstoff","kurz":"Syntetyczny heptapeptyd badany między innymi w modelach szczurzych.","kurz_en":"Syntetyczny heptapeptyd badany między innymi w modelach szczurzych.","quellen":[{"titel":"PubMed: Publikacja badawcza, PMID 14556513","titel_en":"PubMed: Publikacja badawcza, PMID 14556513","url":"https://pubmed.ncbi.nlm.nih.gov/14556513/"}],"text":"Cytowana publikacja bada BDNF w różnych regionach mózgu szczurów. Są to dane przedkliniczne. Nie dowodzą poprawy funkcji poznawczych u ludzi.","text_en":"Cytowana publikacja bada BDNF w różnych regionach mózgu szczurów. Są to dane przedkliniczne. Nie dowodzą poprawy funkcji poznawczych u ludzi.","link":"wirkstoffe/semax.html"},{"slug":"sequenz","begriff":"Sekwencja","begriff_en":"Sekwencja","kategorie":"grundlagen","kurz":"Stała kolejność aminokwasów w łańcuchu peptydu lub białka.","kurz_en":"Stała kolejność aminokwasów w łańcuchu peptydu lub białka.","quellen":[{"titel":"Alberts et al.: Struktura białek","titel_en":"Alberts et al.: Struktura białek","url":"https://www.ncbi.nlm.nih.gov/books/NBK26830/"}],"text":"Sekwencja opisuje kolejność, w jakiej poszczególne aminokwasy są połączone wiązaniami peptydowymi. Zapisuje się ją zwykle za pomocą ujednoliconych kodów jedno- lub trzyliterowych dla każdego aminokwasu. Dwa peptydy zbudowane z tych samych aminokwasów, ale w innej kolejności, to różne cząsteczki, dlatego sekwencja jest kluczowym wyznacznikiem tożsamości.","text_en":"Sekwencja opisuje kolejność, w jakiej poszczególne aminokwasy są połączone wiązaniami peptydowymi. Zapisuje się ją zwykle za pomocą ujednoliconych kodów jedno- lub trzyliterowych dla każdego aminokwasu. Dwa peptydy zbudowane z tych samych aminokwasów, ale w innej kolejności, to różne cząsteczki, dlatego sekwencja jest kluczowym wyznacznikiem tożsamości.","synonyme":["Sekwencja aminokwasów"],"synonyme_en":["Sekwencja aminokwasów"],"siehe":["aminosaeure","peptidbindung","identitaet"]},{"slug":"sermorelin","begriff":"Sermorelin","begriff_en":"Sermorelin","kategorie":"wirkstoff","kurz":"Peptyd pochodny GHRH badany w badaniach endokrynologicznych.","kurz_en":"Peptyd pochodny GHRH badany w badaniach endokrynologicznych.","quellen":[{"titel":"PubMed: Publikacja badawcza, PMID 18031173","titel_en":"PubMed: Publikacja badawcza, PMID 18031173","url":"https://pubmed.ncbi.nlm.nih.gov/18031173/"}],"text":"Powiązany przegląd umieszcza sermorelin w historycznych badaniach nad niedoborem hormonu wzrostu u dzieci. Historyczna literatura medyczna nie ustala ani aktualnego statusu pozwolenia, ani jakości produktu sklepowego.","text_en":"Powiązany przegląd umieszcza sermorelin w historycznych badaniach nad niedoborem hormonu wzrostu u dzieci. Historyczna literatura medyczna nie ustala ani aktualnego statusu pozwolenia, ani jakości produktu sklepowego.","synonyme":["GRF 1-29","GHRH(1-29)","Geref (historyczna nazwa handlowa)"],"synonyme_en":["GRF 1-29","GHRH(1-29)","Geref (historyczna nazwa handlowa)"],"link":"wirkstoffe/sermorelin.html"},{"slug":"ss-31","begriff":"SS-31 (elamipretide)","begriff_en":"SS-31 (elamipretide)","kategorie":"wirkstoff","kurz":"Elamipretide, syntetyczny peptyd badany w badaniach nad zaburzeniami mitochondrialnymi.","kurz_en":"Elamipretide, syntetyczny peptyd badany w badaniach nad zaburzeniami mitochondrialnymi.","quellen":[{"titel":"PubMed: Publikacja badawcza, PMID 37268435","titel_en":"PubMed: Publikacja badawcza, PMID 37268435","url":"https://pubmed.ncbi.nlm.nih.gov/37268435/"},{"titel":"FDA: Forzinity, zatwierdzony 19 września 2025","titel_en":"FDA: Forzinity, zatwierdzony 19 września 2025","url":"https://www.fda.gov/drugs/drug-trials-snapshots/drug-trials-snapshots-forzinity"}],"text":"19 września 2025 r. FDA przyznała przyspieszone zatwierdzenie produktu Forzinity, zawierającego elamipretide, dla określonej grupy pacjentów z zespołem Bartha. To amerykańskie zatwierdzenie produktu nie dotyczy chemikaliów badawczych sprzedawanych jako SS-31.","text_en":"19 września 2025 r. FDA przyznała przyspieszone zatwierdzenie produktu Forzinity, zawierającego elamipretide, dla określonej grupy pacjentów z zespołem Bartha. To amerykańskie zatwierdzenie produktu nie dotyczy chemikaliów badawczych sprzedawanych jako SS-31.","synonyme":["Elamipretide","MTP-131","Bendavia"],"synonyme_en":["Elamipretide","MTP-131","Bendavia"],"link":"wirkstoffe/ss-31.html"},{"slug":"steriles-wasser","begriff":"Woda jałowa","begriff_en":"Woda jałowa","kategorie":"handhabung","kurz":"Woda, dla której jałowość jest określoną cechą produktu.","kurz_en":"Woda, dla której jałowość jest określoną cechą produktu.","quellen":[{"titel":"FDA: Jałowość i endotoksyny","titel_en":"FDA: Jałowość i endotoksyny","url":"https://www.fda.gov/inspections-compliance-enforcement-and-criminal-investigations/inspection-technical-guides/bacterial-endotoxinspyrogens"}],"text":"Jałowość i brak endotoksyn to różne właściwości. Produkty należy oceniać względem ich specyfikacji; słowo „jałowy” nie oznacza ani uniwersalnej przydatności jako rozpuszczalnik, ani określonego okresu trwałości po otwarciu.","text_en":"Jałowość i brak endotoksyn to różne właściwości. Produkty należy oceniać względem ich specyfikacji; słowo „jałowy” nie oznacza ani uniwersalnej przydatności jako rozpuszczalnik, ani określonego okresu trwałości po otwarciu.","siehe":["bakteriostatisches-wasser","rekonstitution","sterilitaet"]},{"slug":"sterilitaet","begriff":"Sterylność","begriff_en":"Sterylność","kategorie":"labor","kurz":"Sterylność oznacza brak żywych mikroorganizmów w próbce, sprawdzany w osobnym badaniu laboratoryjnym.","kurz_en":"Sterylność oznacza brak żywych mikroorganizmów w próbce, sprawdzany w osobnym badaniu laboratoryjnym.","quellen":[{"titel":"FDA: Badanie sterylności i kontrola procesu","titel_en":"FDA: Badanie sterylności i kontrola procesu","url":"https://www.fda.gov/drugs/guidances-drugs/questions-and-answers-current-good-manufacturing-practice-regulations-production-and-process"}],"text":"Badanie jest niezależne od czystości, tożsamości i wartości endotoksyn i jest dokumentowane osobno. Ma znaczenie głównie dla liofilizowanych peptydów, które w warunkach laboratoryjnych rozpuszcza się i dalej przetwarza.","text_en":"Badanie jest niezależne od czystości, tożsamości i wartości endotoksyn i jest dokumentowane osobno. Ma znaczenie głównie dla liofilizowanych peptydów, które w warunkach laboratoryjnych rozpuszcza się i dalej przetwarza.","siehe":["endotoxin","coa"]},{"slug":"studienphasen","begriff":"Fazy badań","begriff_en":"Fazy badań","kategorie":"studien","kurz":"Cztery etapy badań klinicznych: fazy I–III przed dopuszczeniem do obrotu, faza IV po nim, w codziennym stosowaniu.","kurz_en":"Cztery etapy badań klinicznych: fazy I–III przed dopuszczeniem do obrotu, faza IV po nim, w codziennym stosowaniu.","quellen":[{"titel":"FDA: Fazy badań klinicznych","titel_en":"FDA: Fazy badań klinicznych","url":"https://www.fda.gov/patients/drug-development-process/step-3-clinical-research"}],"text":"Rozwój kliniczny opisuje się często w czterech fazach: faza I bada głównie bezpieczeństwo i tolerancję u zdrowych ochotników lub pacjentów. Faza II sprawdza wstępne dowody skuteczności i dalsze pytania dotyczące bezpieczeństwa. Faza III bada to w większych grupach. Faza IV obejmuje badania po dopuszczeniu do obrotu. Sama faza nie przesądza o jakości pojedynczego badania.","text_en":"Rozwój kliniczny opisuje się często w czterech fazach: faza I bada głównie bezpieczeństwo i tolerancję u zdrowych ochotników lub pacjentów. Faza II sprawdza wstępne dowody skuteczności i dalsze pytania dotyczące bezpieczeństwa. Faza III bada to w większych grupach. Faza IV obejmuje badania po dopuszczeniu do obrotu. Sama faza nie przesądza o jakości pojedynczego badania.","synonyme":["Fazy I–IV"],"synonyme_en":["Fazy I–IV"],"siehe":["klinische-studie","rct"],"seiten":["studien.html"]},{"slug":"survodutid","begriff":"Survodutyd","begriff_en":"Survodutyd","kategorie":"wirkstoff","kurz":"Podwójny agonista receptorów glukagonu i GLP-1 badany w badaniach klinicznych.","kurz_en":"Podwójny agonista receptorów glukagonu i GLP-1 badany w badaniach klinicznych.","quellen":[{"titel":"PubMed: Publikacja badawcza, PMID 38330987","titel_en":"PubMed: Publikacja badawcza, PMID 38330987","url":"https://pubmed.ncbi.nlm.nih.gov/38330987/"}],"text":"Powiązane badanie fazy II bada survodutyd jako podwójnego agonistę receptorów. Dane z badania dotyczą testowanej formulacji i populacji i nie weryfikują jakości chemikaliów badawczych.","text_en":"Powiązane badanie fazy II bada survodutyd jako podwójnego agonistę receptorów. Dane z badania dotyczą testowanej formulacji i populacji i nie weryfikują jakości chemikaliów badawczych.","synonyme":["BI 456906"],"synonyme_en":["BI 456906"],"link":"wirkstoffe/survodutid.html"},{"slug":"tb-500","begriff":"TB-500","begriff_en":"TB-500","kategorie":"wirkstoff","kurz":"Nazwa używana w oryginalnej publikacji analitycznej dla acetylowanego fragmentu tymozyny beta-4.","kurz_en":"Nazwa używana w oryginalnej publikacji analitycznej dla acetylowanego fragmentu tymozyny beta-4.","quellen":[{"titel":"PubMed: Publikacja badawcza, PMID 23084823","titel_en":"PubMed: Publikacja badawcza, PMID 23084823","url":"https://pubmed.ncbi.nlm.nih.gov/23084823/"}],"text":"Powiązana publikacja analityczna identyfikuje acetylowany fragment w produkcie oznaczonym jako TB-500. Wyniki dla pełnej długości tymozyny beta-4 nie mają automatycznie zastosowania do tego fragmentu ani do innych produktów dostępnych na rynku.","text_en":"Powiązana publikacja analityczna identyfikuje acetylowany fragment w produkcie oznaczonym jako TB-500. Wyniki dla pełnej długości tymozyny beta-4 nie mają automatycznie zastosowania do tego fragmentu ani do innych produktów dostępnych na rynku.","synonyme":["Fragment tymozyny beta-4","TB4 Frag"],"synonyme_en":["Fragment tymozyny beta-4","TB4 Frag"],"link":"wirkstoffe/tb-500.html"},{"slug":"tesamorelin","begriff":"Tesamorelin","begriff_en":"Tesamorelin","kategorie":"wirkstoff","kurz":"Syntetyczny analog czynnika uwalniającego hormon wzrostu badany w badaniach klinicznych.","kurz_en":"Syntetyczny analog czynnika uwalniającego hormon wzrostu badany w badaniach klinicznych.","quellen":[{"titel":"PubMed: Publikacja badawcza, PMID 18057338","titel_en":"PubMed: Publikacja badawcza, PMID 18057338","url":"https://pubmed.ncbi.nlm.nih.gov/18057338/"}],"text":"Cytowana publikacja kliniczna bada czynnik uwalniający hormon wzrostu u osób z HIV. Kontekst kliniczny i preparat badany ograniczają możliwość uogólniania wyników.","text_en":"Cytowana publikacja kliniczna bada czynnik uwalniający hormon wzrostu u osób z HIV. Kontekst kliniczny i preparat badany ograniczają możliwość uogólniania wyników.","synonyme":["Egrifta","TH9507","Egrifta WR"],"synonyme_en":["Egrifta","TH9507","Egrifta WR"],"link":"wirkstoffe/tesamorelin.html"},{"slug":"thymosin-alpha-1","begriff":"Tymozyna alfa 1","begriff_en":"Tymozyna alfa 1","kategorie":"wirkstoff","kurz":"Peptyd z układu tymozyn badany w badaniach klinicznych i przedklinicznych.","kurz_en":"Peptyd z układu tymozyn badany w badaniach klinicznych i przedklinicznych.","quellen":[{"titel":"PubMed: Publikacja badawcza, PMID 3998766","titel_en":"PubMed: Publikacja badawcza, PMID 3998766","url":"https://pubmed.ncbi.nlm.nih.gov/3998766/"}],"text":"Powiązane badanie randomizowane bada syntetyczną tymozynę alfa-1 w określonym kontekście onkologicznym. Taki wynik nie jest ogólnym dowodem wzmocnienia odporności i nie weryfikuje swobodnie sprzedawanych produktów badawczych.","text_en":"Powiązane badanie randomizowane bada syntetyczną tymozynę alfa-1 w określonym kontekście onkologicznym. Taki wynik nie jest ogólnym dowodem wzmocnienia odporności i nie weryfikuje swobodnie sprzedawanych produktów badawczych.","synonyme":["Tα1","Zadaxin (nazwa handlowa)"],"synonyme_en":["Tα1","Zadaxin (nazwa handlowa)"],"link":"wirkstoffe/thymosin-alpha-1.html"},{"slug":"thymosine","begriff":"Tymozyny","begriff_en":"Tymozyny","kategorie":"klassen","kurz":"Tymozyny to rodzina peptydów pierwotnie wyizolowanych z grasicy.","kurz_en":"Tymozyny to rodzina peptydów pierwotnie wyizolowanych z grasicy.","quellen":[{"titel":"NCI: Tymozyny","titel_en":"NCI: Tymozyny","url":"https://www.cancer.gov/publications/dictionaries/cancer-drug/def/recombinant-thymosin"}],"text":"Nazwa obejmuje różne peptydy pierwotnie wyizolowane z materiału grasiczego. Tymozyny alfa i beta różnią się budową i kontekstem badawczym. Wyniki dla jednej tymozyny nie mają automatycznie zastosowania do pozostałych.","text_en":"Nazwa obejmuje różne peptydy pierwotnie wyizolowane z materiału grasiczego. Tymozyny alfa i beta różnią się budową i kontekstem badawczym. Wyniki dla jednej tymozyny nie mają automatycznie zastosowania do pozostałych.","synonyme":["Peptydy tymozyny"],"synonyme_en":["Peptydy tymozyny"],"siehe":["peptidhormon","protein"],"wirkstoffe":["thymosin-alpha-1","tb-500"],"seiten":["peptid-1x1.html"]},{"slug":"tiermodell","begriff":"Model zwierzęcy","begriff_en":"Model zwierzęcy","kategorie":"studien","kurz":"Zwierzę laboratoryjne, takie jak mysz lub szczur, używane do badania substancji in vivo. Nie jest to bezpośredni dowód dla ludzi.","kurz_en":"Zwierzę laboratoryjne, takie jak mysz lub szczur, używane do badania substancji in vivo. Nie jest to bezpośredni dowód dla ludzi.","quellen":[{"titel":"NCI: model zwierzęcy","titel_en":"NCI: model zwierzęcy","url":"https://www.cancer.gov/publications/dictionaries/cancer-terms/def/animal-model"}],"text":"Model zwierzęcy to zwierzę laboratoryjne, takie jak mysz, szczur lub danio pręgowany, na którym w kontrolowanych warunkach bada się metabolizm, zachowanie lub tkanki. Służy do badań przedklinicznych przed ewentualnym badaniem klinicznym. Ponieważ genetyka i fizjologia się różnią, efekt w modelu zwierzęcym nie jest dowodem efektu u ludzi.","text_en":"Model zwierzęcy to zwierzę laboratoryjne, takie jak mysz, szczur lub danio pręgowany, na którym w kontrolowanych warunkach bada się metabolizm, zachowanie lub tkanki. Służy do badań przedklinicznych przed ewentualnym badaniem klinicznym. Ponieważ genetyka i fizjologia się różnią, efekt w modelu zwierzęcym nie jest dowodem efektu u ludzi.","siehe":["in-vivo","praeklinisch"],"seiten":["studien.html"]},{"slug":"tirzepatid","begriff":"Tirzepatyd","begriff_en":"Tirzepatyd","kategorie":"wirkstoff","kurz":"Podwójny agonista receptorów GIP i GLP-1 badany w badaniach klinicznych.","kurz_en":"Podwójny agonista receptorów GIP i GLP-1 badany w badaniach klinicznych.","quellen":[{"titel":"PubMed: Publikacja badawcza, PMID 35658024","titel_en":"PubMed: Publikacja badawcza, PMID 35658024","url":"https://pubmed.ncbi.nlm.nih.gov/35658024/"}],"text":"Powiązane randomizowane badanie kliniczne bada tirzepatyd w otyłości. Jego preparat badany i kontrole jakości należy odróżniać od swobodnie dostępnych chemikaliów badawczych.","text_en":"Powiązane randomizowane badanie kliniczne bada tirzepatyd w otyłości. Jego preparat badany i kontrole jakości należy odróżniać od swobodnie dostępnych chemikaliów badawczych.","synonyme":["LY3298176"],"synonyme_en":["LY3298176"],"link":"wirkstoffe/tirzepatid.html"},{"slug":"u-100","begriff":"U-100","begriff_en":"U-100","kategorie":"handhabung","kurz":"Oznaczenie insuliny zawierającej 100 jednostek na mililitr, a nie ogólna jednostka dla peptydów.","kurz_en":"Oznaczenie insuliny zawierającej 100 jednostek na mililitr, a nie ogólna jednostka dla peptydów.","quellen":[{"titel":"DailyMed: Znaczenie oznaczenia U-100","titel_en":"DailyMed: Znaczenie oznaczenia U-100","url":"https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=c8ecbd7a-0e22-4fc7-a503-faa58c1b6f3f"}],"text":"U-100 to oznaczenie stężenia produktów insulinowych. Nie jest ogólną jednostką masy peptydów. Skali oznaczonej w ten sposób nie można interpretować jako ilości peptydu bez znajomości substancji i jej specyfikacji.","text_en":"U-100 to oznaczenie stężenia produktów insulinowych. Nie jest ogólną jednostką masy peptydów. Skali oznaczonej w ten sposób nie można interpretować jako ilości peptydu bez znajomości substancji i jej specyfikacji.","siehe":["internationale-einheit","konzentration"]},{"slug":"vial","begriff":"Fiolka","begriff_en":"Fiolka","kategorie":"handhabung","kurz":"Fiolka to mały szklany pojemnik, zwykle zamknięty gumowym korkiem, zawierający peptyd w postaci proszku lub roztworu.","kurz_en":"Fiolka to mały szklany pojemnik, zwykle zamknięty gumowym korkiem, zawierający peptyd w postaci proszku lub roztworu.","quellen":[{"titel":"ICH Q7: Produkcja, partie i certyfikaty analizy","titel_en":"ICH Q7: Produkcja, partie i certyfikaty analizy","url":"https://www.fda.gov/media/71518/download"}],"text":"Fiolki są standardowym opakowaniem liofilizowanych peptydów w handlu materiałami badawczymi. Gumowy korek umożliwia pobieranie w układzie zamkniętym, a wydrukowana etykieta zwykle zawiera numer partii i ilość. Pojedynczą fiolkę można dopasować do CoA, o ile numer partii się zgadza.","text_en":"Fiolki są standardowym opakowaniem liofilizowanych peptydów w handlu materiałami badawczymi. Gumowy korek umożliwia pobieranie w układzie zamkniętym, a wydrukowana etykieta zwykle zawiera numer partii i ilość. Pojedynczą fiolkę można dopasować do CoA, o ile numer partii się zgadza.","synonyme":["Buteleczka"],"synonyme_en":["Buteleczka"],"siehe":["charge","lyophilisat","aliquot"]},{"slug":"wachstumshormon","begriff":"Hormon wzrostu","begriff_en":"Hormon wzrostu","kategorie":"klassen","kurz":"Hormon wzrostu to hormon przysadki, który reguluje wzrost, metabolizm i skład ciała.","kurz_en":"Hormon wzrostu to hormon przysadki, który reguluje wzrost, metabolizm i skład ciała.","quellen":[{"titel":"NIDDK: Hormon wzrostu i IGF-1","titel_en":"NIDDK: Hormon wzrostu i IGF-1","url":"https://www.niddk.nih.gov/health-information/endocrine-diseases/acromegaly"}],"langform":"Somatotropina","langform_en":"Somatotropina","text":"Hormon wzrostu, zwany też somatotropiną lub GH, jest wytwarzany przez komórki somatotropowe w przysadce i uwalniany do krwi w impulsach, kontrolowanych przez GHRH, somatostatynę i grelinę. Reguluje wzrost na długość, metabolizm mięśni i tłuszczów oraz gęstość kości, zarówno bezpośrednio, jak i przez IGF-1 z wątroby. Kilka klas peptydów oddziałuje na różne punkty tej osi, w tym na uwalnianie z przedniego płata przysadki.","text_en":"Hormon wzrostu, zwany też somatotropiną lub GH, jest wytwarzany przez komórki somatotropowe w przysadce i uwalniany do krwi w impulsach, kontrolowanych przez GHRH, somatostatynę i grelinę. Reguluje wzrost na długość, metabolizm mięśni i tłuszczów oraz gęstość kości, zarówno bezpośrednio, jak i przez IGF-1 z wątroby. Kilka klas peptydów oddziałuje na różne punkty tej osi, w tym na uwalnianie z przedniego płata przysadki.","synonyme":["GH","HGH","Somatotropina"],"synonyme_en":["GH","HGH","Somatotropina"],"siehe":["ghrh","ghrp","igf-1"],"wirkstoffe":["cjc-1295","tesamorelin","sermorelin","ipamorelin","hexarelin"],"seiten":["peptid-1x1.html"]},{"slug":"wada","begriff":"WADA","begriff_en":"WADA","kategorie":"recht","kurz":"WADA publikuje coroczną listę substancji zabronionych w sporcie, która obejmuje również peptydy.","kurz_en":"WADA publikuje coroczną listę substancji zabronionych w sporcie, która obejmuje również peptydy.","quellen":[{"titel":"WADA: Aktualna lista zakazanych substancji","titel_en":"WADA: Aktualna lista zakazanych substancji","url":"https://www.wada-ama.org/en/prohibited-list"}],"langform":"Światowa Agencja Antydopingowa","langform_en":"Światowa Agencja Antydopingowa","text":"Światowa Agencja Antydopingowa koordynuje przepisy antydopingowe w sporcie zorganizowanym i co roku aktualizuje listę zabronionych substancji. Kilka kategorii obejmuje hormony peptydowe i substancje pokrewne, niezależnie od ich statusu prawnego poza sportem. To, jaka konkretna substancja jest objęta listą, wynika wyłącznie z aktualnej listy WADA.","text_en":"Światowa Agencja Antydopingowa koordynuje przepisy antydopingowe w sporcie zorganizowanym i co roku aktualizuje listę zabronionych substancji. Kilka kategorii obejmuje hormony peptydowe i substancje pokrewne, niezależnie od ich statusu prawnego poza sportem. To, jaka konkretna substancja jest objęta listą, wynika wyłącznie z aktualnej listy WADA.","seiten":["faq.html"]},{"slug":"zulassung","begriff":"Pozwolenie na dopuszczenie do obrotu","begriff_en":"Pozwolenie na dopuszczenie do obrotu","kategorie":"recht","kurz":"Pozwolenie na dopuszczenie do obrotu to wymagana zgoda organu regulacyjnego na sprzedaż produktu leczniczego na rynku.","kurz_en":"Pozwolenie na dopuszczenie do obrotu to wymagana zgoda organu regulacyjnego na sprzedaż produktu leczniczego na rynku.","quellen":[{"titel":"EMA: Oceny i decyzje o pozwoleniu","titel_en":"EMA: Oceny i decyzje o pozwoleniu","url":"https://www.ema.europa.eu/en/about-us/what-we-do/authorisation-medicines/how-ema-evaluates-medicines-human-use"}],"text":"W scentralizowanej procedurze UE EMA ocenia dokumentację naukową. Komisja Europejska udziela pozwolenia na dopuszczenie do obrotu. Pozwolenie dotyczy konkretnego produktu leczniczego na określonych warunkach, a nie każdego produktu o tej samej nazwie substancji.","text_en":"W scentralizowanej procedurze UE EMA ocenia dokumentację naukową. Komisja Europejska udziela pozwolenia na dopuszczenie do obrotu. Pozwolenie dotyczy konkretnego produktu leczniczego na określonych warunkach, a nie każdego produktu o tej samej nazwie substancji.","synonyme":["Pozwolenie na dopuszczenie do obrotu"],"synonyme_en":["Pozwolenie na dopuszczenie do obrotu"],"siehe":["ema","fda","arzneimittel"],"seiten":["peptid-1x1.html"]}];
